-- Vorrats-Aufgaben (rollend-12) in bestehende Flüge einfügen: 210 Aufgaben, 13 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (1, 'zahlen.natuerlich', 805, 26, $auf$[{"l": "stellenwert", "t": "stellenwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Teile die Zahl durch 10. Weg B: Zähle zusammen, wie viele Zehner in den Tausendern, in den Hundertern und in den Zehnern stecken. Wie viele Zehner stecken insgesamt in der Zahl 4 560?"}, "o": {"wert": 456, "einheit": "Zehner"}, "h": "Ein Tausender besteht aus vielen Zehnern. Wie viele sind es?", "w": "Weg A: 4 560 : 10 = 456. Weg B: 4 Tausender sind 400 Zehner, 5 Hunderter sind 50 Zehner, dazu 6 Zehner: 400 + 50 + 6 = 456. Beide Wege geben 456 Zehner.", "form": "zwei_wege", "zaehlt": "ja", "r": 12806}, {"l": "stellenwert", "t": "stellenwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Zähler wurde um 4 Tausender und 5 Zehner erhöht. Jetzt zeigt er 12 078. Welche Zahl zeigte er vorher?"}, "o": {"wert": 8028}, "h": "Gehe den Weg rückwärts: Was musst du von der neuen Zahl wieder wegnehmen?", "w": "Erhöht wurde um 4 000 + 50 = 4 050. Rückwärts wird abgezogen: 12 078 − 4 050 = 8 028. Probe: 8 028 + 4 050 = 12 078.", "form": "umkehren", "zaehlt": "ja", "r": 12807}, {"l": "zahlwort_zu_ziffern", "t": "zahlwort_zu_ziffern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Zahl lautet „dreihundertzwölf Millionen vierzigtausend“. Weg A: Schreibe die ganze Zahl mit Ziffern hin und lies die Stelle ab. Weg B: Suche im Zahlwort den Teil, der die Zehntausender enthält, und lies dort die Ziffer ab. Welche Ziffer steht an der Zehntausenderstelle?"}, "o": {"wert": 4, "einheit": "Ziffer"}, "h": "Die Zehntausenderstelle ist die fünfte Stelle von rechts. Welcher Teil des Zahlworts liefert sie?", "w": "Weg A: 312 040 000, von rechts gezählt: Einer 0, Zehner 0, Hunderter 0, Tausender 0, Zehntausender 4. Weg B: Die Millionen reichen nur bis zur Millionenstelle; „vierzigtausend“ ist 40 000 und hat 4 Zehntausender.", "form": "zwei_wege", "zaehlt": "ja", "r": 12808}, {"l": "zahlwort_zu_ziffern", "t": "zahlwort_zu_ziffern", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "auswahl", "f": {"text": "Vier Zahlen sind als Zahlwort angegeben. Schreibe sie in Ziffern. Welches Zahlwort gehört zu der Zahl, die in Ziffern geschrieben die meisten Nullen hat?"}, "a": ["zwei Millionen dreißigtausend", "zwanzig Millionen dreitausend", "zweihundert Millionen drei", "zweihunderttausenddreißig"], "o": {"index": 2}, "h": "Schreibe zuerst jede Zahl mit Ziffern. Zähle dann die Nullen.", "w": "„zweihundert Millionen drei“ ist 200 000 003 mit sieben Nullen. 2 030 000 hat fünf, 20 003 000 hat sechs, 200 030 hat vier Nullen.", "form": "bruecke", "zaehlt": "ja", "r": 12809}, {"l": "ziffern_zu_zahlwort", "t": "ziffern_zu_zahlwort", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Verein erhält eine Spende von 40 306 Euro. Der Betrag soll auf der Quittung in Worten stehen. Welche Schreibweise ist richtig?"}, "a": ["vierzigtausenddreihundertsechs Euro", "vierzigtausenddreihundertsechzig Euro", "viertausenddreihundertsechs Euro", "dreiundvierzigtausendsechs Euro"], "o": {"index": 0}, "h": "Lies die Zahl in Gruppen: erst die Tausender, dann Hunderter, Zehner und Einer. Eine Null bleibt stumm.", "w": "40 306 hat 40 Tausender und 306 Einer: „vierzigtausend“ und „dreihundertsechs“, zusammen „vierzigtausenddreihundertsechs“.", "form": "anwenden", "zaehlt": "ja", "r": 12810}, {"l": "ziffern_zu_zahlwort", "t": "ziffern_zu_zahlwort", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Tim schreibt die Zahl 70 305 in Worten. Zeile 1: 70 305 hat 7 Zehntausender, 0 Tausender, 3 Hunderter, 0 Zehner und 5 Einer. Zeile 2: 7 Zehntausender sind siebzigtausend. Zeile 3: 3 Hunderter und 5 Einer sind dreihundertfünfzig. Zeile 4: Zusammen heißt die Zahl siebzigtausenddreihundertfünfzig. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich und schreibe die Zahl selbst in Worten auf. Welche Aussage stimmt zum ersten Mal nicht?", "w": "3 Hunderter und 5 Einer sind 305, also „dreihundertfünf“ (die Zehnerstelle ist leer). Richtig: siebzigtausenddreihundertfünf. Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12811}, {"l": "strahl_ablesen", "t": "strahl_ablesen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf einem Zahlenstrahl sind die Marken 4 000 und 5 000 beschriftet. Zwischen ihnen liegen 10 gleich große Abschnitte. Ein Pfeil steht nach dem 7. Abschnitt, von 4 000 aus gezählt. Weg A: Bestimme die Länge eines Abschnitts und zähle von 4 000 aus vor. Weg B: Zähle von 5 000 aus zurück. Welche Zahl zeigt der Pfeil?"}, "o": {"wert": 4700}, "h": "Wie viele Abschnitte liegen zwischen dem Pfeil und der Marke 5 000?", "w": "Ein Abschnitt ist (5 000 − 4 000) : 10 = 100 lang. Weg A: 4 000 + 7 · 100 = 4 700. Weg B: Bis 5 000 sind es noch 3 Abschnitte: 5 000 − 3 · 100 = 4 700.", "form": "zwei_wege", "zaehlt": "ja", "r": 12812}, {"l": "strahl_ablesen", "t": "strahl_ablesen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Auf einem Zahlenstrahl ist die Marke 1 450 beschriftet. Ein Pfeil zeigt auf die Zahl 1 585. Er steht auf dem 3. Strich rechts von der Marke 1 450. Alle Striche haben gleichen Abstand. Welche Zahl gehört zum 4. Strich rechts von 1 450?"}, "o": {"wert": 1630}, "h": "Was weißt du über den Abstand zweier Striche? Wie kannst du ihn aus den Angaben bestimmen?", "w": "Von 1 450 bis 1 585 sind es 135 in 3 Abschnitten, ein Abschnitt ist also 135 : 3 = 45 lang. Der 4. Strich liegt einen Abschnitt hinter dem Pfeil: 1 585 + 45 = 1 630. Probe: 1 450 + 4 · 45 = 1 630.", "form": "umkehren", "zaehlt": "ja", "r": 12813}, {"l": "strahl_eintragen", "t": "strahl_eintragen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Ein Zahlenstrahl beginnt bei 0 und endet bei 600. Er ist in 12 gleich große Abschnitte geteilt. Die Zahl 350 soll eingetragen werden. Nach wie vielen Abschnitten, von 0 aus gezählt, liegt sie?"}, "o": {"wert": 7, "einheit": "Abschnitte"}, "h": "Wie lang ist ein Abschnitt in Zahlen?", "w": "Ein Abschnitt ist 600 : 12 = 50 lang. 350 : 50 = 7. Die Zahl 350 liegt nach 7 Abschnitten.", "form": "bruecke", "zaehlt": "ja", "r": 12814}, {"l": "strahl_eintragen", "t": "strahl_eintragen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Zahlenstrahl geht von 0 bis 400 und ist in 8 gleiche Abschnitte geteilt. Mia will die Zahl 250 eintragen. Zeile 1: Ein Abschnitt ist 400 : 8 = 40 lang. Zeile 2: Es gilt 250 : 40 = 6 Rest 10. Zeile 3: Die Marke liegt also 6 Abschnitte und noch ein Stück rechts von der 0. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und mache bei den Rechnungen die Gegenprobe. Welche Aussage stimmt zum ersten Mal nicht?", "w": "400 : 8 = 50, nicht 40 (8 · 40 = 320). Richtig: ein Abschnitt ist 50 lang, 250 : 50 = 5, die Marke 250 liegt genau 5 Abschnitte von der 0 entfernt. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12815}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Einwohner vier Orte haben. Wie viele Einwohner hat der Ort mit der drittgrößten Einwohnerzahl?", "grafik": {"typ": "tabelle", "kopf": ["Ort", "Einwohner"], "zeilen": [["Altbach", "48 305"], ["Bergau", "48 350"], ["Clausen", "40 835"], ["Dorfen", "84 053"]]}}, "o": {"wert": 48305, "einheit": "Einwohner"}, "h": "Ordne die vier Zahlen der Größe nach. Beginne mit der größten.", "w": "Der Größe nach: 84 053 > 48 350 > 48 305 > 40 835. Die drittgrößte Zahl ist 48 305.", "form": "bruecke", "zaehlt": "ja", "r": 12816}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "In der Schulbücherei stehen vier Regale. Sie enthalten 1 205, 1 250, 1 052 und 1 502 Bücher. Wie viele Bücher mehr stehen im vollsten Regal als im leersten?"}, "o": {"wert": 450, "einheit": "Bücher"}, "h": "Finde zuerst das Regal mit den meisten und das mit den wenigsten Büchern. Dann vergleiche.", "w": "Die meisten Bücher hat das Regal mit 1 502, die wenigsten das mit 1 052. 1 502 − 1 052 = 450.", "form": "anwenden", "zaehlt": "ja", "r": 12817}, {"l": "runden_regel", "t": "runden_regel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Wende die Rundungsregel an und sieh dir die Ziffer rechts neben der Rundungsstelle an. Weg B: Schreibe die beiden benachbarten vollen Hunderter auf und prüfe, zu welchem 7 349 näher liegt. Runde 7 349 auf volle Hunderter."}, "o": {"wert": 7300}, "h": "Die Rundungsstelle ist die Hunderterstelle. Welche Ziffer rechts daneben entscheidet?", "w": "Weg A: Rechts neben den Hundertern steht die 4 (Zehnerstelle). 4 ist kleiner als 5, also wird abgerundet: 7 300. Weg B: Die Nachbarn sind 7 300 und 7 400. Der Abstand zu 7 300 ist 49, zu 7 400 ist 51. 7 300 ist näher.", "form": "zwei_wege", "zaehlt": "ja", "r": 12818}, {"l": "runden_regel", "t": "runden_regel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mara rundet 38 428 auf volle Hunderter. Zeile 1: Die Hunderterstelle von 38 428 ist die 4. Zeile 2: Die Ziffer links neben der 4 ist die 8. Weil 8 mindestens 5 ist, wird aufgerundet. Zeile 3: Aus 4 Hundertern werden 5 Hunderter, rechts stehen Nullen: 38 500. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich: Stimmt die Aussage, und folgt der Schritt aus der Rundungsregel? Welche Zeile enthält zuerst einen Fehler?", "w": "Entscheidend ist die Ziffer rechts neben der Rundungsstelle, hier die 2 der Zehnerstelle. 2 ist kleiner als 5, also wird abgerundet: 38 400. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12819}, {"l": "runden_uebertrag", "t": "runden_uebertrag", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Eine Zeitung meldet die Besucherzahlen eines Museums, jeweils auf volle Hunderter gerundet. In der Tabelle stehen die echten Zahlen von sechs Tagen. An wie vielen dieser Tage steht in der Zeitung 3 000?", "grafik": {"typ": "tabelle", "kopf": ["Tag", "Besucher"], "zeilen": [["Mo", "2 949"], ["Di", "2 950"], ["Mi", "3 049"], ["Do", "3 050"], ["Fr", "2 987"], ["Sa", "3 012"]]}}, "o": {"wert": 4, "einheit": "Tage"}, "h": "Runde jede Zahl der Tabelle einzeln auf Hunderter. Achte auf die Zehnerziffer.", "w": "Gerundet: 2 949 → 2 900; 2 950 → 3 000; 3 049 → 3 000; 3 050 → 3 100; 2 987 → 3 000; 3 012 → 3 000. An 4 Tagen steht 3 000.", "form": "bruecke", "zaehlt": "ja", "r": 12820}, {"l": "runden_uebertrag", "t": "runden_uebertrag", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine ganze Zahl wurde mit der üblichen Rundungsregel (ab 5 wird aufgerundet) auf volle Hunderter gerundet und ergibt 8 000. Welches ist die kleinste ganze Zahl, bei der das passiert?"}, "o": {"wert": 7950}, "h": "Teste Zahlen knapp unter 8 000: Welche werden noch zu 8 000, welche schon zu 7 900?", "w": "Aufgerundet wird ab einer Zehnerziffer 5. Der kleinere volle Hunderter ist 7 900. Die kleinste Zahl, die zu 8 000 aufgerundet wird, ist 7 950. 7 949 würde zu 7 900 abgerundet.", "form": "umkehren", "zaehlt": "ja", "r": 12821}, {"l": "runden_sinnvoll", "t": "runden_sinnvoll", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Für 342 Personen sollen Busse bestellt werden. In jeden Bus passen 50 Personen. Weg A: Teile und runde sinnvoll. Weg B: Zähle die Plätze für 1, 2, 3 … Busse auf, bis es reicht. Wie viele Busse werden mindestens gebraucht?"}, "o": {"wert": 7, "einheit": "Busse"}, "h": "Passen 342 Personen in 6 Busse? Probiere es.", "w": "Weg A: 342 : 50 = 6 Rest 42. Die 42 Personen brauchen noch einen Bus: 7 Busse. Weg B: 6 Busse haben 300 Plätze, das reicht nicht. 7 Busse haben 350 Plätze, das reicht.", "form": "zwei_wege", "zaehlt": "ja", "r": 12822}, {"l": "runden_sinnvoll", "t": "runden_sinnvoll", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Klasse bestellt Pizza. 47 Personen essen je 2 Stücke. Eine Pizza hat 8 Stücke. Nico rechnet. Zeile 1: 47 Personen essen zusammen 47 · 2 = 94 Stücke. Zeile 2: 94 geteilt durch 8 ergibt 11 Rest 6. Zeile 3: Es reichen 11 Pizzen, denn die übrigen 6 Stücke sind weniger als eine ganze Pizza. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich: Rechnet sie richtig, und passt der Schluss zur Aufgabe? Welche Zeile enthält zuerst einen Fehler?", "w": "11 Pizzen haben nur 11 · 8 = 88 Stücke, es fehlen 6. Man muss aufrunden: 12 Pizzen (96 Stücke). Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12823}, {"l": "unendlich", "t": "unendlich", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Tim behauptet: „999 999 ist die größte natürliche Zahl.“ Du widerlegst das mit dem Nachfolger. Weg A: Addiere 1 zu 999 999. Weg B: Beginne bei 999 997 und zähle drei Schritte weiter. Wie heißt der Nachfolger von 999 999?"}, "o": {"wert": 1000000}, "h": "Welche Zahl kommt unmittelbar nach 999 999? Was geschieht mit den Neunen?", "w": "Weg A: 999 999 + 1 = 1 000 000. Weg B: 999 997, 999 998, 999 999, 1 000 000: Nach drei Schritten steht man bei 1 000 000, und das ist der Nachfolger von 999 999. Der Nachfolger ist größer, also ist Tims Zahl nicht die größte. Dasselbe gilt für jede Zahl, die jemand als größte nennt: Ihr Nachfolger ist größer. Darum gibt es keine größte natürliche Zahl.", "form": "zwei_wege", "zaehlt": "ja", "r": 12824}, {"l": "unendlich", "t": "unendlich", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Anna behauptet, 2 000 000 sei die größte natürliche Zahl. Welche Begründung zeigt, dass es überhaupt keine größte natürliche Zahl gibt?"}, "a": ["Die Zahl 2 000 001 ist größer als 2 000 000.", "Die Zahl 1 000 000 000 ist größer als 2 000 000.", "Die Zahl 5 000 000 ist größer als 2 000 000.", "Für jede vorgeschlagene natürliche Zahl n ist n + 1 eine größere natürliche Zahl."], "o": {"index": 3}, "h": "Eine Begründung muss für jede vorgeschlagene Zahl gelten, nicht nur für 2 000 000.", "w": "Zu jeder natürlichen Zahl n gibt es den Nachfolger n + 1, und der ist größer. Das gilt für 2 000 000 genauso wie für jede andere vorgeschlagene Zahl, darum kann keine Zahl die größte sein. Die anderen Aussagen nennen nur eine einzelne größere Zahl und begründen nichts für jeden Vorschlag.", "form": "anwenden", "zaehlt": "ja", "r": 12825}, {"l": "roemisch_schreiben", "t": "roemisch_schreiben", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Über dem Eingang einer Schule soll das Baujahr 1984 in römischen Zahlzeichen stehen. Welche Schreibweise ist richtig?"}, "a": ["MCMLXXXVI", "MCMLXXXIV", "MDCLXXXIV", "MCMLXXIV"], "o": {"index": 1}, "h": "Zerlege 1984 in Tausender, Hunderter, Zehner und Einer. Schreibe jeden Teil einzeln.", "w": "1984 = 1000 + 900 + 80 + 4 = M + CM + LXXX + IV = MCMLXXXIV.", "form": "anwenden", "zaehlt": "ja", "r": 12826}, {"l": "roemisch_schreiben", "t": "roemisch_schreiben", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Lena schreibt die Zahl 49 in römischen Zahlzeichen. Zeile 1: 49 ist 50 − 1. Zeile 2: Das Zeichen für 50 ist L, das Zeichen für 1 ist I. Zeile 3: Ein kleineres Zeichen vor einem größeren wird abgezogen, also darf die I direkt vor der L stehen. Zeile 4: Also schreibt man 49 als IL. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich und denke an die Regeln für das Abziehen bei römischen Zahlen. Welche Zeile enthält zuerst einen Fehler?", "w": "Das Abziehen ist eingeschränkt: Die I darf nur vor V und X stehen, die X nur vor L und C. 49 = 40 + 9 = XL + IX = XLIX. Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12827}, {"l": "roemisch_system", "t": "roemisch_system", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Das Doppelte einer Zahl ist MCM. Welche römische Zahl ist es, und warum zählt das C in MCM nicht 100, sondern wird abgezogen?"}, "a": ["ML, denn das C steht zwischen zwei M und wird addiert.", "CML, denn das C steht vor dem größeren Zeichen M und wird deshalb abgezogen: MCM ist 1 900, die Hälfte ist 950.", "MMMDCCC, denn das C steht vor dem größeren Zeichen M und wird abgezogen; die 1 900 werden dann verdoppelt."], "o": {"index": 1}, "h": "Schreibe MCM zuerst mit Ziffern. Rechne dann rückwärts.", "w": "MCM ist 1 900 (M = 1 000 und CM = 900). Die Zahl ist die Hälfte: 1 900 : 2 = 950. 950 = 900 + 50 = CM + L = CML. Probe: 2 · 950 = 1 900. Das Zeichen C hat immer den Grundwert 100. Steht ein kleineres Zeichen vor einem größeren Zeichen, das direkt folgt (hier C vor M), wird es abgezogen: CM = 1 000 − 100 = 900. Das Zeichen behält seinen Wert, nur seine Stellung vor oder nach einem anderen Zeichen entscheidet, ob addiert oder abgezogen wird.", "form": "umkehren", "zaehlt": "ja", "r": 12828}, {"l": "roemisch_system", "t": "roemisch_system", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Römische Zahlen haben keinen Stellenwert und keine Null. Die Zahl 888 hat in Ziffern 3 Zeichen. Bei 888 benötigt jeder der drei Teile 800, 80 und 8 vier römische Zeichen. Wie viele Zeichen mehr braucht ihre römische Schreibweise (DCCCLXXXVIII)?"}, "o": {"wert": 9, "einheit": "Zeichen"}, "h": "Zähle die Zeichen D, C, L, X, V und I in der römischen Zahl einzeln. Was gehört zu den Ziffern 8?", "w": "888 = 800 + 80 + 8 = DCCC + LXXX + VIII. Jede 8 braucht 4 Zeichen (ein Fünfer-Zeichen und drei Einer-Zeichen), zusammen 12 Zeichen. In Ziffern sind es 3. Also 12 − 3 = 9 Zeichen mehr.", "form": "anwenden", "zaehlt": "ja", "r": 12829}, {"l": "dualsystem", "t": "dualsystem", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Addiere die Stellenwerte 1, 2, 4, 8, 16, 32 dort, wo eine 1 steht. Weg B: Gehe von links nach rechts: Verdopple die bisherige Zahl und addiere die nächste Ziffer. Welche Zahl im Zehnersystem steht hinter der Dualzahl 101101?"}, "o": {"wert": 45}, "h": "Von rechts nach links verdoppeln sich die Stellenwerte: 1, 2, 4 …", "w": "Weg A: 32 + 8 + 4 + 1 = 45. Weg B: 1, dann 1 · 2 + 0 = 2, 2 · 2 + 1 = 5, 5 · 2 + 1 = 11, 11 · 2 + 0 = 22, 22 · 2 + 1 = 45.", "form": "zwei_wege", "zaehlt": "ja", "r": 12830}, {"l": "dualsystem", "t": "dualsystem", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ben schreibt die Zahl 13 als Dualzahl. Zeile 1: 13 = 8 + 4 + 1. Zeile 2: Die Stellenwerte sind 8, 4, 2, 1. Also steht bei 8 eine 1, bei 4 eine 0, bei 2 eine 1 und bei 1 eine 1. Zeile 3: Die Dualzahl ist 1011. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und rechne die Dualzahl zur Probe zurück. Welche Zeile enthält zuerst einen Fehler?", "w": "In 13 = 8 + 4 + 1 kommt die 2 nicht vor. Richtig: bei 8 eine 1, bei 4 eine 1, bei 2 eine 0, bei 1 eine 1: 1101. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12831}]$auf$::jsonb),
    (4, 'zahlen.teilbarkeit', 658, 14, $auf$[{"l": "teiler", "t": "teiler", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Aus quadratischen Fliesen soll ein Rechteck mit der Fläche 36 Fliesen gelegt werden, beide Seitenlängen sind ganze Zahlen. Ein Rechteck 4 × 9 und ein Rechteck 9 × 4 gelten als dasselbe Rechteck. Wie viele verschiedene Rechtecke gibt es?"}, "o": {"wert": 5, "einheit": "Rechtecke"}, "h": "Zu jeder Seitenlänge, die 36 teilt, gehört eine passende zweite Seitenlänge. Welche Zahlen teilen 36?", "w": "Die Teiler von 36 sind 1, 2, 3, 4, 6, 9, 12, 18, 36. Paare: 1 × 36, 2 × 18, 3 × 12, 4 × 9, 6 × 6. Das sind 5 Rechtecke (6 × 6 ist ein Quadrat und zählt einmal).", "form": "bruecke", "zaehlt": "ja", "r": 12659}, {"l": "teiler", "t": "teiler", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Zahl kleiner als 50 hat genau 3 Teiler. Es gibt mehrere solche Zahlen. Wie heißt die größte davon?"}, "o": {"wert": 49}, "h": "Eine Zahl mit genau 3 Teilern hat die Teiler 1, eine Zahl a und sich selbst. Wie hängen a und die Zahl zusammen?", "w": "Die Teiler sind 1, a und die Zahl selbst. Das geht nur, wenn die Zahl a · a ist und a eine Primzahl ist. Solche Zahlen unter 50 sind 4, 9, 25 und 49. Die größte ist 49 = 7 · 7 mit den Teilern 1, 7 und 49.", "form": "umkehren", "zaehlt": "ja", "r": 12660}, {"l": "vielfache", "t": "vielfache", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Betrachte die Zahlen von 105 bis 203 einschließlich beider Grenzen. Weg A: Schreibe die Vielfachen der Reihe nach auf und zähle. Weg B: Bestimme, das wievielte Vielfache von 7 die 105 und das wievielte die 203 ist, und rechne mit diesen beiden Nummern. Gib die Zahl der Vielfachen an."}, "o": {"wert": 15, "einheit": "Vielfache"}, "h": "Welche Vielfachen von 7 sind 105 und 203? Gehören die Grenzen dazu?", "w": "Weg A: 105, 112, 119, …, 196, 203 sind 15 Zahlen. Weg B: 105 = 15 · 7 ist das 15. Vielfache, 203 = 29 · 7 ist das 29. Vielfache. Von der 15. bis zur 29. Nummer sind es 29 − 15 + 1 = 15 Vielfache, weil beide Grenzen mitzählen.", "form": "zwei_wege", "zaehlt": "ja", "r": 12661}, {"l": "vielfache", "t": "vielfache", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Bus der Linie A fährt alle 15 Minuten, ein Bus der Linie B alle 20 Minuten. Um 8:00 Uhr fahren beide gleichzeitig ab. Nach wie vielen Minuten fahren beide zum ersten Mal wieder gleichzeitig ab?"}, "o": {"wert": 60, "einheit": "Minuten"}, "h": "Wann sind beide Busse gleichzeitig an der Haltestelle? Was haben die Abfahrtszeiten mit Vielfachen zu tun?", "w": "Vielfache von 15: 15, 30, 45, 60, … Vielfache von 20: 20, 40, 60, … Die erste gemeinsame Zahl ist 60. Nach 60 Minuten fahren beide wieder gleichzeitig ab.", "form": "anwenden", "zaehlt": "ja", "r": 12662}, {"l": "endziffer", "t": "endziffer", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Eine Kasse hat nur 5-Euro-Scheine und 10-Euro-Scheine. Welcher Betrag kann damit nicht genau bezahlt werden?"}, "a": ["4 902 €", "275 €", "340 €", "1 205 €"], "o": {"index": 0}, "h": "Alle Beträge, die man mit 5-Euro-Scheinen zahlen kann, sind Vielfache von 5. Woran erkennt man Vielfache von 5?", "w": "Vielfache von 5 enden auf 0 oder 5. 275, 340 und 1 205 enden auf 5 oder 0. 4 902 endet auf 2, ist also kein Vielfaches von 5 und lässt sich mit 5-€- und 10-€-Scheinen nicht genau zahlen.", "form": "anwenden", "zaehlt": "ja", "r": 12663}, {"l": "endziffer", "t": "endziffer", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Prüfe die Endziffern. Weg B: Überlege, wie viele Vielfache von 5 es bis 150 und wie viele es unter 100 gibt. Wie viele Zahlen von 100 bis 150 (beide Grenzen eingeschlossen) sind durch 5 teilbar?"}, "o": {"wert": 11, "einheit": "Zahlen"}, "h": "Bis 99 gibt es 19 Vielfache von 5 (5 bis 95). Wie viele sind es bis 150?", "w": "Weg A: Endziffer 0 oder 5: 100, 105, …, 150 sind 11 Zahlen. Weg B: Bis 150 gibt es 30 Vielfache, bis 99 gibt es 19. 30 − 19 = 11.", "form": "zwei_wege", "zaehlt": "ja", "r": 12664}, {"l": "quersumme", "t": "quersumme", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Bei einer Tombola gewinnt jedes Los, dessen Nummer durch 3 teilbar ist. Welches dieser Lose gewinnt?"}, "a": ["Los 2 378", "Los 4 123", "Los 1 245", "Los 5 606"], "o": {"index": 2}, "h": "Eine Zahl ist durch 3 teilbar, wenn ihre Quersumme durch 3 teilbar ist.", "w": "Quersummen: 1 245 → 12 (durch 3 teilbar), 2 378 → 20, 4 123 → 10, 5 606 → 17. Nur 12 ist durch 3 teilbar, es gewinnt Los 1 245.", "form": "anwenden", "zaehlt": "ja", "r": 12665}, {"l": "quersumme", "t": "quersumme", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Gegeben ist die Zahl 2 749. Weg A: Dividiere schriftlich. Weg B: Bilde die Quersumme und bestimme ihren Rest bei der Division durch 3. Welchen Rest lässt 2 749 bei der Division durch 3?"}, "o": {"wert": 1}, "h": "Bei Weg B zählst du zuerst die Ziffern zusammen.", "w": "Weg A schriftlich: 27 : 3 = 9 Rest 0; die 4 herunterholen: 4 : 3 = 1 Rest 1; die 9 herunterholen: 19 : 3 = 6 Rest 1. Ergebnis: 2 749 : 3 = 916 Rest 1. Weg B: Quersumme 2 + 7 + 4 + 9 = 22, 22 : 3 = 7 Rest 1. Beide Wege geben Rest 1.", "form": "zwei_wege", "zaehlt": "ja", "r": 12666}, {"l": "neunerregel", "t": "neunerregel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Fabrik verpackt 5 873 Stifte in Packungen zu je 9 Stück. Wie viele Stifte bleiben übrig, wenn so viele volle Packungen wie möglich gefüllt werden?"}, "o": {"wert": 5, "einheit": "Stifte"}, "h": "Womit kannst du den Rest bei Division durch 9 finden, ohne zu dividieren?", "w": "Quersumme: 5 + 8 + 7 + 3 = 23. 23 : 9 = 2 Rest 5. Also bleibt Rest 5. Kontrolle: 5 873 = 9 · 652 + 5.", "form": "anwenden", "zaehlt": "ja", "r": 12667}, {"l": "neunerregel", "t": "neunerregel", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Prüfe bei jeder Zahl die Quersumme. Weg B: Überlege, wie viele Vielfache von 9 es bis 130 und wie viele es bis 99 gibt. Wie viele Zahlen von 100 bis 130 sind durch 9 teilbar?"}, "o": {"wert": 3, "einheit": "Zahlen"}, "h": "Bis 99 sind es 11 Vielfache von 9 (9 bis 99). Bis 130?", "w": "Weg A: Quersumme durch 9 teilbar nur bei 108, 117 und 126. Weg B: Bis 130: 130 : 9 = 14 Rest 4, also 14 Vielfache. Bis 99: 11. 14 − 11 = 3.", "form": "zwei_wege", "zaehlt": "ja", "r": 12668}, {"l": "primzahl", "t": "primzahl", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Summe zweier Primzahlen ist 20. Eine der beiden Zahlen ist 3. Wie heißt die andere Zahl?"}, "o": {"wert": 17}, "h": "Mache die Addition rückgängig. Prüfe dann, ob das Ergebnis eine Primzahl ist.", "w": "20 − 3 = 17. 17 ist eine Primzahl, denn sie hat nur die Teiler 1 und 17. Probe: 3 + 17 = 20.", "form": "umkehren", "zaehlt": "ja", "r": 12669}, {"l": "primzahl", "t": "primzahl", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Prüfe jede Zahl auf Teiler. Weg B: Schreibe alle Zahlen von 31 bis 49 auf und streiche alle Vielfachen von 2, 3, 5 und 7. Wie viele Primzahlen liegen zwischen 30 und 50?"}, "o": {"wert": 5, "einheit": "Primzahlen"}, "h": "Primzahlen sind größer als 1 und haben nur zwei Teiler. Gerade Zahlen über 2 fallen sofort weg.", "w": "Es bleiben 31, 37, 41, 43 und 47. Bei 49 = 7 · 7 ist 7 ein Teiler. Bei Weg B werden Vielfache von 2, 3, 5 und 7 gestrichen, denn 11 · 11 ist schon größer als 50.", "form": "zwei_wege", "zaehlt": "ja", "r": 12670}, {"l": "primfaktoren", "t": "primfaktoren", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt, wie 180 durch Teilen zerlegt wurde: Jedes Mal wurde die Zahl durch die kleinste passende Primzahl geteilt, bis 1 übrig blieb. Welche Primfaktorzerlegung von 180 steht in der Tabelle?", "grafik": {"typ": "tabelle", "kopf": ["Zahl", "geteilt durch", "Ergebnis"], "zeilen": [["180", "2", "90"], ["90", "2", "45"], ["45", "3", "15"], ["15", "3", "5"], ["5", "5", "1"]]}}, "a": ["2 · 2 · 3 · 3 · 5 · 5", "2 · 3 · 5", "2 · 2 · 3 · 3 · 5"], "o": {"index": 2}, "h": "Welche Spalte der Tabelle enthält die Primzahlen, durch die geteilt wurde?", "w": "Die Teiler in der Tabelle sind 2, 2, 3, 3 und 5. Es sind alles Primzahlen und das Produkt ist 2 · 2 · 3 · 3 · 5 = 180.", "form": "bruecke", "zaehlt": "ja", "r": 12671}, {"l": "primfaktoren", "t": "primfaktoren", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Boden ist 84 cm lang und 126 cm breit. Er soll lückenlos mit möglichst großen quadratischen Platten belegt werden, ohne dass eine Platte zerschnitten wird. Wie lang ist eine Seite einer Platte?"}, "o": {"wert": 42, "einheit": "cm"}, "h": "Welche Eigenschaft muss die Seitenlänge der Platten für 84 cm und für 126 cm haben?", "w": "84 = 2 · 2 · 3 · 7 und 126 = 2 · 3 · 3 · 7. Gemeinsam sind 2, 3 und 7. 2 · 3 · 7 = 42. Die Platten sind 42 cm lang. Probe: 84 : 42 = 2 und 126 : 42 = 3.", "form": "anwenden", "zaehlt": "ja", "r": 12672}]$auf$::jsonb),
    (13, 'daten.darstellen', 582, 12, $auf$[{"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei einer Umfrage unter 30 Kindern nannten 12 Kinder Fußball und 8 Kinder Schwimmen als Lieblingssport. Alle übrigen Kinder nannten Tanzen. Wie oft wurde Tanzen genannt?"}, "o": {"wert": 10, "einheit": "Nennungen"}, "h": "Wie viele Kinder haben schon etwas anderes genannt? Was bleibt von allen Befragten übrig?", "w": "Fußball und Schwimmen zusammen: 12 + 8 = 20 Nennungen. Von 30 Kindern bleiben 30 − 20 = 10 für Tanzen. Probe: 12 + 8 + 10 = 30.", "form": "umkehren", "zaehlt": "ja", "r": 12583}, {"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Kiosk zählt, wie viele Eis er von Montag bis Freitag verkauft: Montag 12, Dienstag 15, Mittwoch 9, Donnerstag 18, Freitag 21. Am Wochenende (Samstag und Sonntag zusammen) verkauft er ein Drittel so viele Eis wie von Montag bis Freitag zusammen. Wie viele Eis verkauft er in der ganzen Woche?"}, "o": {"wert": 100, "einheit": "Eis"}, "h": "Wie viele Eis wurden von Montag bis Freitag verkauft? Worauf bezieht sich das Drittel?", "w": "Montag bis Freitag: 12 + 15 + 9 + 18 + 21 = 75 Eis. Ein Drittel davon: 75 : 3 = 25 Eis am Wochenende. Insgesamt 75 + 25 = 100 Eis.", "form": "anwenden", "zaehlt": "ja", "r": 12584}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Erweitere den Bruch 18/25 auf den Nenner 100. Weg B: Rechne 18 : 25 und schreibe das Ergebnis in Prozent. Gib 18 von 25 als Prozentzahl an."}, "o": {"wert": 72, "einheit": "%"}, "h": "Mit welcher Zahl musst du 25 malnehmen, um 100 zu erhalten?", "w": "Weg A: 25 · 4 = 100, also 18 · 4 = 72 und 18/25 = 72/100 = 72 %. Weg B: 18 : 25 = 0,72 und 0,72 = 72 %.", "form": "zwei_wege", "zaehlt": "ja", "r": 12585}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "An einer Schule lernen 400 Kinder. 30 % davon sind Fahrschüler. Die Hälfte der Fahrschüler kommt mit dem Bus. Wie viele Kinder kommen mit dem Bus?"}, "o": {"wert": 60, "einheit": "Kinder"}, "h": "Berechne zuerst, wie viele Kinder Fahrschüler sind.", "w": "30 % von 400 sind 400 : 100 · 30 = 120 Fahrschüler. Die Hälfte davon: 120 : 2 = 60 Kinder.", "form": "anwenden", "zaehlt": "ja", "r": 12586}, {"l": "tabelle_auswerten", "t": "tabelle_auswerten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Tabelle zeigt eine Umfrage zum Lieblingssport. Weg A: Addiere die Anzahlen aller anderen Sportarten. Weg B: Berechne zuerst, wie viele Kinder insgesamt befragt wurden, und ziehe dann die Anzahl für Fußball ab. Wie viele Kinder haben nicht „Fußball“ gewählt?", "grafik": {"typ": "tabelle", "kopf": ["Sportart", "Anzahl Kinder"], "zeilen": [["Fußball", "11"], ["Schwimmen", "6"], ["Tennis", "4"], ["Tanzen", "7"]]}}, "o": {"wert": 17, "einheit": "Kinder"}, "h": "Welche Zeilen der Tabelle zählen zu „nicht Fußball“?", "w": "Weg A: Schwimmen 6 + Tennis 4 + Tanzen 7 = 17. Weg B: Insgesamt 11 + 6 + 4 + 7 = 28 Kinder. 28 − 11 = 17.", "form": "zwei_wege", "zaehlt": "ja", "r": 12587}, {"l": "tabelle_auswerten", "t": "tabelle_auswerten", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Eis ein Kiosk an vier Tagen verkauft hat. Ein Eis kostet 2 €. Wie viel Euro hat der Kiosk an den zwei Tagen mit den meisten verkauften Eis zusammen eingenommen?", "grafik": {"typ": "tabelle", "kopf": ["Tag", "Verkaufte Eis"], "zeilen": [["Montag", "35"], ["Dienstag", "28"], ["Mittwoch", "41"], ["Donnerstag", "33"]]}}, "o": {"wert": 152, "einheit": "€"}, "h": "Finde die beiden Tage mit den meisten Eis. Wie viele Eis sind das zusammen?", "w": "Die meisten Eis gab es am Mittwoch (41) und am Montag (35). Zusammen 41 + 35 = 76 Eis. 76 · 2 € = 152 €.", "form": "anwenden", "zaehlt": "ja", "r": 12588}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Das Säulendiagramm zeigt, wie viele Kinder in vier Klassen eine Brezel bestellt haben. Eine Brezel kostet 70 Cent. Wie viel Euro kosten alle bestellten Brezeln?", "grafik": {"typ": "saeulen", "werte": [{"name": "5a", "wert": 14}, {"name": "5b", "wert": 11}, {"name": "5c", "wert": 9}, {"name": "5d", "wert": 16}]}}, "o": {"wert": 35, "einheit": "€"}, "h": "Lies die vier Säulen ab und zähle sie zusammen. Wie viele Brezeln sind das?", "w": "Bestellt wurden 14 + 11 + 9 + 16 = 50 Brezeln. 50 · 70 Cent = 3 500 Cent = 35 €.", "form": "bruecke", "zaehlt": "ja", "r": 12589}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Säulendiagramm zeigt vier Klassen. Die ersten drei Säulen sind 12, 7 und 15 Kinder hoch, die vierte Säule ist verdeckt. Insgesamt wurden 50 Kinder befragt. Wie hoch ist die verdeckte Säule?"}, "o": {"wert": 16, "einheit": "Kinder"}, "h": "Wie viele Kinder zeigen die drei sichtbaren Säulen zusammen? Wie viele fehlen bis 50?", "w": "Die drei sichtbaren Säulen zeigen 12 + 7 + 15 = 34 Kinder. Es fehlen 50 − 34 = 16 Kinder. Die verdeckte Säule ist 16 hoch.", "form": "umkehren", "zaehlt": "ja", "r": 12590}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt, welchen Anteil vier Sportarten bei einer Umfrage haben. Daraus wird ein Kreisdiagramm gezeichnet. Wie groß ist der Winkel des Sektors „Schwimmen“?", "grafik": {"typ": "tabelle", "kopf": ["Sportart", "Anteil"], "zeilen": [["Fußball", "25 %"], ["Schwimmen", "10 %"], ["Tanzen", "40 %"], ["Sonstige", "25 %"]]}}, "o": {"wert": 36, "einheit": "°"}, "h": "Ein ganzer Kreis hat 360°. Wie viel Grad entsprechen 1 %?", "w": "1 % entspricht 360° : 100 = 3,6°. Für 10 % ist der Winkel 10 · 3,6° = 36°.", "form": "bruecke", "zaehlt": "ja", "r": 12591}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Im Kreisdiagramm einer Umfrage hat ein Sektor den Winkel 72°. Insgesamt wurden 60 Personen befragt. Wie viele Personen gehören zu diesem Sektor?"}, "o": {"wert": 12, "einheit": "Personen"}, "h": "Welcher Bruchteil des ganzen Kreises sind 72°?", "w": "72° von 360° sind 72/360 = 1/5 des Kreises. Ein Fünftel von 60 Personen sind 60 : 5 = 12 Personen.", "form": "umkehren", "zaehlt": "ja", "r": 12592}, {"l": "irrefuehrend", "t": "irrefuehrend", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Hochachse eines Säulendiagramms beginnt bei 500. Die erste Säule steht für 520 und ist 2 cm hoch gezeichnet. Die zweite Säule wirkt 3-mal so hoch wie die erste. Für welchen Wert steht die zweite Säule?"}, "o": {"wert": 560}, "h": "Welcher Zuwachs über 500 gehört zu 2 cm? Was bedeutet 3-mal so hoch?", "w": "2 cm stehen für 520 − 500 = 20. Die zweite Säule ist 3 · 2 cm = 6 cm hoch, das sind 3 · 20 = 60 über 500. Wert: 500 + 60 = 560.", "form": "umkehren", "zaehlt": "ja", "r": 12593}, {"l": "irrefuehrend", "t": "irrefuehrend", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Firma zeigt ein Säulendiagramm, dessen Hochachse bei 8 000 € beginnt. Der Umsatz 2024 war 8 400 €, der Umsatz 2025 war 9 200 €. Wie oft so hoch wie die Säule für 2024 wirkt die Säule für 2025?"}, "o": {"wert": 3}, "h": "Die Achse beginnt nicht bei null. Wie hoch sind die Säulen über 8 000 gezeichnet?", "w": "Über der Achsenmarke 8 000 ragen die Säulen 400 und 1 200 hinaus. 1 200 : 400 = 3. Die zweite Säule wirkt 3-mal so hoch, obwohl der Umsatz nur um etwa 10 % gestiegen ist.", "form": "anwenden", "zaehlt": "ja", "r": 12594}]$auf$::jsonb),
    (28, 'messen.koerper_darstellung', 589, 12, $auf$[{"l": "prisma", "t": "prisma", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Kanten Prismen mit verschiedenen Grundflächen haben. Wie viele Kanten hat ein Prisma mit sechseckiger Grundfläche?", "grafik": {"typ": "tabelle", "kopf": ["Grundfläche", "Kanten des Prismas"], "zeilen": [["Dreieck", "9"], ["Viereck", "12"], ["Fünfeck", "15"]]}}, "o": {"wert": 18, "einheit": "Kanten"}, "h": "Erkenne das Muster: Wie viele Kanten kommen jedes Mal dazu, wenn die Grundfläche eine Ecke mehr hat?", "w": "Mit jeder zusätzlichen Ecke kommen 3 Kanten dazu (eine in der Grundfläche, eine in der Deckfläche, eine seitlich). 15 + 3 = 18. Auch: 3 · 6 = 18.", "form": "bruecke", "zaehlt": "ja", "r": 12590}, {"l": "prisma", "t": "prisma", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Nico zählt die Flächen eines Prismas mit sechseckiger Grundfläche. Zeile 1: Das Prisma hat zwei Sechsecke als Grund- und Deckfläche. Zeile 2: Die Zahl der Seitenflächen ist doppelt so groß wie die Zahl der Ecken der Grundfläche: 2 · 6 = 12. Zeile 3: Insgesamt hat das Prisma 2 + 12 = 14 Flächen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und überlege, wie viele Seitenflächen zu den Seiten der Grundfläche gehören. Welche Zeile enthält zuerst einen Fehler?", "w": "Zu jeder Seite der Grundfläche gehört eine Seitenfläche, hier also 6. Insgesamt: 2 + 6 = 8 Flächen. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12591}, {"l": "netz", "t": "netz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Würfelschachtel hat die Kantenlänge 5 cm. Sie wird aus einem Netz gefaltet. Wie viele cm² Pappe braucht man für das Netz, wenn man keine Klebelaschen rechnet?"}, "o": {"wert": 150, "einheit": "cm²"}, "h": "Aus wie vielen Quadraten besteht das Netz eines Würfels? Wie groß ist jedes?", "w": "Das Netz besteht aus 6 Quadraten. Jedes hat 5 · 5 = 25 cm². 6 · 25 cm² = 150 cm².", "form": "anwenden", "zaehlt": "ja", "r": 12592}, {"l": "netz", "t": "netz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Quader ist 5 cm lang, 4 cm breit und 3 cm hoch. Weg A: Berechne alle sechs Rechtecke einzeln und addiere. Weg B: Berechne die beiden Grundflächen (5 cm × 4 cm) und dazu ein langes Rechteck, dessen Länge der Umfang der Grundfläche und dessen Höhe 3 cm ist. Wie groß ist die Oberfläche seines Netzes?"}, "o": {"wert": 94, "einheit": "cm²"}, "h": "Bei Weg B: Wie groß ist der Umfang der Grundfläche 5 cm × 4 cm?", "w": "Weg A: 20 + 20 + 15 + 15 + 12 + 12 = 94 cm². Weg B: Zwei Grundflächen 2 · 20 = 40 cm². Umfang der Grundfläche 2 · (5 + 4) = 18 cm, langes Rechteck 18 · 3 = 54 cm². 40 + 54 = 94 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 12593}, {"l": "zylinder", "t": "zylinder", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Im Netz eines Zylinders ist das Mantelrechteck 37,68 cm lang und 10 cm hoch. Rechne mit π ≈ 3,14. Wie groß ist der Radius des Grundkreises?"}, "o": {"wert": 6, "einheit": "cm"}, "h": "Die Länge des Mantelrechtecks ist genauso lang wie ein Umfang. Welcher Kreis hat diesen Umfang?", "w": "Die Länge des Mantelrechtecks ist der Umfang des Grundkreises: u = 37,68 cm. Aus u = 2 · π · r folgt r = 37,68 : (2 · 3,14) = 37,68 : 6,28 = 6 cm.", "form": "bruecke", "zaehlt": "ja", "r": 12594}, {"l": "zylinder", "t": "zylinder", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Zylinder hat den Radius 3 cm und die Höhe 10 cm. Tim berechnet die Mantelfläche mit π ≈ 3,14. Zeile 1: Der Umfang des Grundkreises ist u = 3,14 · 3 = 9,42 cm. Zeile 2: Die Mantelfläche ist u · h = 9,42 · 10 = 94,2 cm². Zeile 3: Der Mantel des Zylinders hat also etwa 94,2 cm². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und vergleiche mit der Formel für den Kreisumfang. Welche Zeile enthält zuerst einen Fehler?", "w": "Der Umfang ist u = 2 · π · r = 2 · 3,14 · 3 = 18,84 cm. Die Mantelfläche ist 18,84 · 10 = 188,4 cm². Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12595}, {"l": "schraegbild", "t": "schraegbild", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Tiefe eines Quaders wird im Schrägbild (q = 1/2) mit 3,5 cm gezeichnet. Wie tief ist der Quader in Wirklichkeit?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Beim Schrägbild werden die nach hinten laufenden Kanten auf die Hälfte verkürzt. Mache das rückgängig.", "w": "Die gezeichnete Länge ist die Hälfte der wirklichen: 3,5 cm = 1/2 · wirkliche Tiefe. Wirkliche Tiefe: 3,5 · 2 = 7 cm.", "form": "umkehren", "zaehlt": "ja", "r": 12596}, {"l": "schraegbild", "t": "schraegbild", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Quader ist 8 cm lang, 4 cm hoch und 6 cm tief. Lena zeichnet ein Schrägbild mit q = 1/2. Zeile 1: Die Vorderseite (8 cm × 4 cm) wird unverändert gezeichnet. Zeile 2: Die nach hinten laufenden Kanten werden mit q = 1/2 verkürzt: 6 · 2 = 12 cm. Zeile 3: Die schrägen Kanten werden also 12 cm lang gezeichnet. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und frage, ob die Rechnung zum Verkürzen passt. Welche Zeile enthält zuerst einen Fehler?", "w": "Mit q = 1/2 wird die Tiefe halbiert: 6 · 1/2 = 3 cm. Die schrägen Kanten sind 3 cm lang. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12597}, {"l": "ansichten", "t": "ansichten", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle nennt für vier Körper die Vorderansicht und die Draufsicht. Bei wie vielen der vier Körper sind beide Ansichten dieselbe Art von Figur (zum Beispiel beide Rechtecke)?", "grafik": {"typ": "tabelle", "kopf": ["Körper", "Vorderansicht", "Draufsicht"], "zeilen": [["Zylinder", "Rechteck", "Kreis"], ["Kegel", "Dreieck", "Kreis"], ["Quader", "Rechteck", "Rechteck"], ["Würfel", "Quadrat", "Quadrat"]]}}, "o": {"wert": 2, "einheit": "Körper"}, "h": "Vergleiche in jeder Zeile die beiden Figuren.", "w": "Zylinder: Rechteck und Kreis (verschieden). Kegel: Dreieck und Kreis (verschieden). Quader: Rechteck und Rechteck (gleich). Würfel: Quadrat und Quadrat (gleich). Das sind 2 Körper.", "form": "bruecke", "zaehlt": "ja", "r": 12598}, {"l": "ansichten", "t": "ansichten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "auswahl", "f": {"text": "Ein Körper wird von vorn und von der Seite betrachtet. In beiden Fällen sieht man ein Dreieck. Von oben sieht man ein Quadrat. Welcher Körper ist es?"}, "a": ["Kegel", "Dreiecksprisma (liegend)", "Würfel", "Pyramide mit quadratischer Grundfläche"], "o": {"index": 3}, "h": "Was verraten dir die Ansichten von vorn und von der Seite über die Form des Körpers nach oben? Und was die Ansicht von oben über die Grundfläche?", "w": "Dreieck von vorn und von der Seite heißt: Der Körper läuft nach oben spitz zu. Das Quadrat von oben ist die Grundfläche. Das ist die Pyramide mit quadratischer Grundfläche.", "form": "umkehren", "zaehlt": "ja", "r": 12599}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Jan behauptet: „Ein Würfel hat 6 Flächen mit je 4 Kanten, also 24 Kanten.“ Weg A: Zähle die Kanten oben, unten und die senkrechten Kanten. Weg B: Prüfe Jans Rechnung: Jede Kante gehört zu genau zwei Flächen. Gib die wirkliche Zahl der Kanten an."}, "o": {"wert": 12, "einheit": "Kanten"}, "h": "Jede Kante grenzt an zwei Flächen. Wie oft hat Jan jede Kante gezählt?", "w": "Weg A: oben 4, unten 4, senkrecht 4: 4 + 4 + 4 = 12. Weg B: 6 · 4 = 24 Kanten gezählt, aber jede wurde zweimal gezählt: 24 : 2 = 12.", "form": "zwei_wege", "zaehlt": "ja", "r": 12600}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Jan behauptet: „Für ein Kantenmodell aus genau 30 Holzstäben braucht man ein Prisma mit zwölfeckiger Grundfläche.“ Jeder Stab ist eine Kante, alle Stäbe werden gebraucht. Wie viele Ecken hat die Grundfläche des Prismas wirklich?"}, "o": {"wert": 10, "einheit": "Ecken"}, "h": "Prüfe Jans Behauptung: Wie viele Kanten hat ein Prisma mit zwölfeckiger Grundfläche?", "w": "Ein Prisma mit n-eckiger Grundfläche hat n Kanten in der Grundfläche, n in der Deckfläche und n Verbindungskanten, zusammen 3 · n. Bei n = 12 wären es 36 Kanten, nicht 30. Aus 3 · n = 30 folgt n = 10. Das Prisma hat eine zehneckige Grundfläche. Probe: 3 · 10 = 30.", "form": "anwenden", "zaehlt": "ja", "r": 12601}]$auf$::jsonb),
    (39, 'zahlen.ganz', 789, 22, $auf$[{"l": "deuten", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Höhle liegt 12 m unter dem Meeresspiegel (−12 m). Ein Aussichtspunkt liegt 7 m über dem Meeresspiegel (7 m). Weg A: Zähle auf der Zahlengeraden von −12 bis 0 und dann weiter bis 7. Weg B: Rechne 7 − (−12). Wie viele Meter liegt der Aussichtspunkt höher als die Höhle?"}, "o": {"wert": 19, "einheit": "m"}, "h": "Der Meeresspiegel ist die Null. Wie weit ist es von der Höhle bis dorthin?", "w": "Weg A: Von −12 bis 0 sind es 12 Meter, von 0 bis 7 weitere 7 Meter: 12 + 7 = 19. Weg B: 7 − (−12) = 7 + 12 = 19. Der Aussichtspunkt liegt 19 m höher.", "form": "zwei_wege", "zaehlt": "ja", "r": 12790}, {"l": "deuten", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Konto steht auf −45 €. Dann werden 60 € eingezahlt. Tim überlegt, was auf dem Konto steht. Zeile 1: Der Stand −45 € bedeutet, dass 45 € Guthaben auf dem Konto sind. Zeile 2: Nach der Einzahlung sind es 45 + 60 = 105 € Guthaben. Zeile 3: Das Konto zeigt jetzt 105 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und frage, was die Vorzeichen im Alltag bedeuten. Welche Zeile enthält zuerst einen Fehler?", "w": "Ein negativer Kontostand bedeutet Schulden. Aus −45 € werden mit 60 € Einzahlung −45 + 60 = 15 €. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12791}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Von einer Zahl springt man auf der Zahlengeraden zuerst 9 Schritte nach links und dann 4 Schritte nach rechts. Man landet bei −2. Bei welcher Zahl ist man gestartet?"}, "o": {"wert": 3}, "h": "Welche Gesamtbewegung ergeben die beiden Sprünge? Was musst du damit rückwärts tun?", "w": "Die beiden Sprünge ergeben zusammen −9 + 4 = −5, also 5 Schritte nach links. Rückwärts geht man von −2 aus 5 Schritte nach rechts: −2 + 5 = 3. Probe: 3 − 9 + 4 = −2.", "form": "umkehren", "zaehlt": "ja", "r": 12792}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Seil hängt von einer Plattform in 8 m Höhe bis zu einem Anker in 16 m Tiefe. Die Höhe 0 m ist die Wasseroberfläche. Ein Knoten soll genau in der Mitte des Seils befestigt werden. In welcher Höhe in Metern, mit Vorzeichen, ist das?"}, "o": {"wert": -4, "einheit": "m"}, "h": "Welche Zahlen auf der Zahlengeraden gehören zu den beiden Enden des Seils?", "w": "Die Enden liegen bei 8 m und −16 m. Die Mitte ist (8 + (−16)) : 2 = −8 : 2 = −4 m, also 4 m unter der Wasseroberfläche. Probe: Von −4 nach oben und nach unten sind es 12 m.", "form": "anwenden", "zaehlt": "ja", "r": 12793}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt die Temperaturen von sechs Orten in einer Winternacht. An wie vielen Orten ist es kälter als −3 °C?", "grafik": {"typ": "tabelle", "kopf": ["Ort", "Temperatur in °C"], "zeilen": [["Alm", "−8"], ["Brunn", "2"], ["Cella", "−3"], ["Dorn", "−12"], ["Egg", "0"], ["Furt", "−5"]]}}, "o": {"wert": 3, "einheit": "Orte"}, "h": "Kälter heißt: weiter links auf der Zahlengeraden als −3.", "w": "Kälter als −3 °C sind −8 °C, −12 °C und −5 °C. 0 °C, 2 °C und −3 °C selbst sind nicht kälter. Es sind 3 Orte.", "form": "bruecke", "zaehlt": "ja", "r": 12794}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mia ordnet die Zahlen −7, 3, −2 und −10 vom kleinsten zum größten. Zeile 1: Unter den negativen Zahlen ist −2 die kleinste, weil ihr Betrag 2 am kleinsten ist. Zeile 2: Danach kommen −7 und −10, zuletzt kommt 3. Zeile 3: Die Reihenfolge ist also −2, −7, −10, 3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und zeichne die Zahlen in Gedanken auf die Zahlengerade. Welche Zeile enthält zuerst einen Fehler?", "w": "Je weiter links, desto kleiner. Am weitesten links liegt −10, dann −7, dann −2, dann 3. Richtig: −10, −7, −2, 3. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12795}, {"l": "betrag", "t": "ordnen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Auf der Zahlengeraden liegen zwei Zahlen, die beide genau 7 Schritte vom Nullpunkt entfernt sind, aber auf verschiedenen Seiten. Wie viele Schritte sind die beiden Zahlen voneinander entfernt?"}, "o": {"wert": 14, "einheit": "Schritte"}, "h": "Wie heißen die beiden Zahlen? Zeichne dir den Weg von der einen zur anderen.", "w": "Die beiden Zahlen sind −7 und 7. Von −7 bis 0 sind es 7 Schritte, von 0 bis 7 noch einmal 7. Zusammen sind es 14 Schritte.", "form": "bruecke", "zaehlt": "ja", "r": 12796}, {"l": "betrag", "t": "ordnen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Schreibe alle diese Zahlen auf und zähle. Weg B: Überlege, wie weit man vom Nullpunkt nach rechts und nach links gehen darf, und rechne. Wie viele ganze Zahlen x erfüllen |x| < 4?"}, "o": {"wert": 7, "einheit": "Zahlen"}, "h": "Zähle die Null mit. Welche Zahlen haben einen Abstand kleiner als 4 von der Null?", "w": "Weg A: −3, −2, −1, 0, 1, 2, 3 sind 7 Zahlen. Weg B: nach rechts 3 Zahlen, nach links 3 Zahlen und die Null: 3 + 3 + 1 = 7.", "form": "zwei_wege", "zaehlt": "ja", "r": 12797}, {"l": "schriftlich_plus_minus", "t": "schriftlich", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche Zahl musst du zu 4 507 addieren, um 10 000 zu erhalten? Rechne schriftlich."}, "o": {"wert": 5493}, "h": "Rechne rückwärts: Was musst du von 10 000 abziehen? Achte beim Abziehen auf das Borgen.", "w": "Die gesuchte Zahl ist 10 000 − 4 507 = 5 493. Probe: 4 507 + 5 493 = 10 000.", "form": "umkehren", "zaehlt": "ja", "r": 12798}, {"l": "schriftlich_plus_minus", "t": "schriftlich", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eva rechnet schriftlich 7 214 − 3 586 und beginnt bei den Einern. Dabei tauscht sie, wenn nötig, eine Einheit des nächsthöheren Stellenwerts gegen zehn Einheiten der aktuellen Stelle. Zeile 1: Einer: 4 − 6 geht nicht, also 14 − 6 = 8. Ich borge 1. Zeile 2: Zehner: 1 + 10 − 8 − 1 = 2. Ich borge 1. Zeile 3: Hunderter: 2 + 10 − 5 − 1 = 6. Ich borge 1. Zeile 4: Tausender: Dafür muss nichts mehr abgezogen werden, also 7 − 3 = 4. Das Ergebnis ist 4 628. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Prüfe jede Zeile für sich und mache zum Schluss die Probe mit der Addition. Welche Zeile enthält zuerst einen Fehler?", "w": "Beim Tausender muss das geborgte 1 noch abgezogen werden: 7 − 3 − 1 = 3. Richtig: 7 214 − 3 586 = 3 628. Der erste Fehler steht in Zeile 4.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12799}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Rechne von links nach rechts. Weg B: Vertausche die Summanden so, dass sich zwei Zahlen aufheben. Berechne (−47) + 38 + 47 + 15 auf zwei Wegen."}, "o": {"wert": 53}, "h": "Welche zwei Zahlen ergeben zusammen null?", "w": "Weg A: (−47) + 38 = −9, −9 + 47 = 38, 38 + 15 = 53. Weg B: (−47) + 47 = 0, dann 38 + 15 = 53.", "form": "zwei_wege", "zaehlt": "ja", "r": 12800}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Bei einem Spiel gibt es Plus- und Minuspunkte. Jule hat in Runde 1 genau −4 Punkte gemacht, in Runde 2 genau +7 und in Runde 3 genau −13. Sie möchte nach Runde 4 insgesamt genau 5 Punkte haben. Wie viele Punkte muss sie in Runde 4 bekommen?"}, "o": {"wert": 15, "einheit": "Punkte"}, "h": "Wie viele Punkte hat Jule nach drei Runden zusammen? Wie weit ist das von 5 entfernt?", "w": "Nach drei Runden: −4 + 7 − 13 = −10. Bis 5 fehlen 5 − (−10) = 15. In Runde 4 braucht sie 15 Punkte. Probe: −10 + 15 = 5.", "form": "anwenden", "zaehlt": "ja", "r": 12801}, {"l": "subtrahieren", "t": "subtrahieren", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Berechne −5 − (−12). Der Wert ist die Zahl der Schritte, die man auf der Zahlengeraden von −12 bis −5 nach rechts geht. Wie viele Schritte sind das?"}, "o": {"wert": 7, "einheit": "Schritte"}, "h": "Wo liegen −12 und −5 auf der Zahlengeraden? Welche liegt weiter rechts?", "w": "Von −12 bis −5 sind es 12 − 5 = 7 Schritte nach rechts. Auch gerechnet: −5 − (−12) = −5 + 12 = 7.", "form": "bruecke", "zaehlt": "ja", "r": 12802}, {"l": "subtrahieren", "t": "subtrahieren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Lea berechnet 7 − (−4) − 9. Zeile 1: 7 − (−4) = 7 − 4. Zeile 2: 7 − 4 = 3. Zeile 3: 3 − 9 = −6. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und überlege, wie man eine negative Zahl abzieht. Welche Zeile enthält zuerst einen Fehler?", "w": "Minus (−4) ist dasselbe wie plus 4: 7 − (−4) = 7 + 4 = 11. Dann 11 − 9 = 2. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12803}, {"l": "umkehraufgabe", "t": "gleichungen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Auf der Zahlengeraden springt man von einer Zahl x aus 17 Schritte nach rechts und landet bei −9. Welche Zahl ist x?"}, "o": {"wert": -26}, "h": "Gehe den Sprung rückwärts: von −9 aus 17 Schritte in die andere Richtung.", "w": "Der Sprung heißt x + 17 = −9. Rückwärts: x = −9 − 17 = −26. Probe: −26 + 17 = −9.", "form": "bruecke", "zaehlt": "ja", "r": 12804}, {"l": "umkehraufgabe", "t": "gleichungen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Konto wurde um 35 € belastet (Abbuchung) und steht danach auf −12 €. Welchen Kontostand hatte es vorher?"}, "o": {"wert": 23, "einheit": "€"}, "h": "Die Abbuchung hat den Stand um 35 kleiner gemacht. Mache das rückgängig.", "w": "Gleichung: x − 35 = −12. Rückwärts: x = −12 + 35 = 23 €. Probe: 23 − 35 = −12.", "form": "anwenden", "zaehlt": "ja", "r": 12805}, {"l": "ketten", "t": "verbinden", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche ganze Zahl muss im Kästchen stehen, damit die Gleichung stimmt? −2 + □ − 7 + 3 = −14"}, "o": {"wert": -8}, "h": "Fasse die bekannten Zahlen zusammen: −2 − 7 + 3. Was muss □ dann ergeben?", "w": "−2 − 7 + 3 = −6. Also □ + (−6) = −14 und □ = −14 + 6 = −8. Probe: −2 + (−8) − 7 + 3 = −14.", "form": "umkehren", "zaehlt": "ja", "r": 12806}, {"l": "ketten", "t": "verbinden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ben berechnet −14 + 20 − 9 − (−6). Zeile 1: −14 + 20 = 6. Zeile 2: 6 − 9 = −2. Zeile 3: −2 − (−6) = −2 + 6 = 4. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und gehe auf der Zahlengeraden mit. Welche Zeile enthält zuerst einen Fehler?", "w": "6 − 9 = −3. Weiter: −3 − (−6) = −3 + 6 = 3. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12807}, {"l": "verstehen", "t": "begruenden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Lena behauptet: „Wenn ich von 5 eine Zahl abziehe, wird das Ergebnis immer kleiner als 5.“ Betrachte die Zahlen −2, 3, −4, 6, −1, 2 und 7. Weg A: Rechne 5 − b für jede Zahl b aus und vergleiche mit 5. Weg B: Überlege nur mit dem Vorzeichen von b, was beim Abziehen passiert. Bei wie vielen der Zahlen stimmt Lenas Behauptung nicht?"}, "o": {"wert": 3, "einheit": "Zahlen"}, "h": "Was passiert mit 5, wenn man eine negative Zahl abzieht?", "w": "Weg A: 5 − (−2) = 7, 5 − 3 = 2, 5 − (−4) = 9, 5 − 6 = −1, 5 − (−1) = 6, 5 − 2 = 3, 5 − 7 = −2. Größer als 5 wird es bei −2, −4 und −1. Weg B: Das Abziehen einer negativen Zahl macht größer, also sind alle drei negativen Zahlen Gegenbeispiele.", "form": "zwei_wege", "zaehlt": "ja", "r": 12808}, {"l": "verstehen", "t": "begruenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Tom behauptet: „Wenn man etwas abzieht, wird das Ergebnis immer kleiner.“ Anna findet ein Gegenbeispiel. Sie zieht eine Zahl b von 4 ab und erhält 11. Welche Zahl hat Anna abgezogen?"}, "o": {"wert": -7}, "h": "Muss b größer oder kleiner als null sein, damit 4 − b größer als 4 wird?", "w": "Aus 4 − b = 11 folgt b = 4 − 11 = −7. Probe: 4 − (−7) = 4 + 7 = 11. Das Abziehen einer negativen Zahl macht größer, deshalb widerlegt dieses Beispiel die Behauptung.", "form": "umkehren", "zaehlt": "ja", "r": 12809}, {"l": "sach", "t": "verbinden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spielkonto steht am Anfang auf −20 Punkten. Dann gibt es Gewinne von 50 und 10 Punkten und einen Verlust von 35 Punkten. Weg A: Rechne die Änderungen der Reihe nach. Weg B: Fasse Gewinne und Verlust zusammen und rechne dann mit dem Anfangsstand. Welchen Stand hat das Spielkonto am Ende?"}, "o": {"wert": 5, "einheit": "Punkte"}, "h": "Bei Weg B: Wie viel ist es insgesamt, wenn du 50 und 10 gewinnst und 35 verlierst?", "w": "Weg A: −20 + 50 = 30, 30 + 10 = 40, 40 − 35 = 5. Weg B: Gewinne und Verlust zusammen: 50 + 10 − 35 = 25. Dann −20 + 25 = 5.", "form": "zwei_wege", "zaehlt": "ja", "r": 12810}, {"l": "sach", "t": "verbinden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Taucher ist auf −18 m. Er steigt 7 m, sinkt dann 12 m und steigt dann 5 m. Paul berechnet, wo er jetzt ist. Zeile 1: Nach dem Aufsteigen: −18 + 7 = −11. Zeile 2: Nach dem Sinken: −11 − 12 = −23. Zeile 3: Nach dem Aufsteigen: −23 + 5 = −28. Zeile 4: Der Taucher ist bei −28 m. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich und überlege, ob die Höhe beim Steigen größer oder kleiner wird. Welche Zeile enthält zuerst einen Fehler?", "w": "−23 + 5 = −18, denn man geht 5 Schritte nach rechts. Der Taucher ist bei −18 m. Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12811}]$auf$::jsonb),
    (41, 'zahlen.potenzen_basis', 558, 14, $auf$[{"l": "schreibweise", "t": "begriff", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Schreibe die Potenz als Produkt gleicher Faktoren und rechne. Weg B: Schreibe 4 als 2 · 2, bilde daraus eine Potenz mit der Basis 2 und rechne diese aus. Berechne 4³ auf zwei Wegen."}, "o": {"wert": 64}, "h": "Wie oft kommt die 2 insgesamt als Faktor vor, wenn du 4 · 4 · 4 mit 4 = 2 · 2 aufschreibst?", "w": "Weg A: 4³ = 4 · 4 · 4 = 64. Weg B: 4³ = (2 · 2) · (2 · 2) · (2 · 2) = 2 · 2 · 2 · 2 · 2 · 2 = 2⁶ = 64.", "form": "zwei_wege", "zaehlt": "ja", "r": 12559}, {"l": "schreibweise", "t": "begriff", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Am Tag 1 kennt eine Person ein Geheimnis. An jedem weiteren Tag erzählt jede Person, die es am Vortag neu erfahren hat, das Geheimnis genau drei Personen weiter, die es noch nicht kennen. Alle Empfänger sind verschieden. Wie viele Personen erfahren das Geheimnis am Tag 5 neu?"}, "o": {"wert": 81, "einheit": "Personen"}, "h": "Wie viele Personen erfahren es am Tag 2? Am Tag 3? Erkennst du ein Muster mit gleichen Faktoren?", "w": "Tag 2: 3 neue Personen, Tag 3: 3 · 3 = 9, Tag 4: 27, Tag 5: 3 · 3 · 3 · 3 = 3⁴ = 81. Der Exponent ist um 1 kleiner als die Nummer des Tages.", "form": "anwenden", "zaehlt": "ja", "r": 12560}, {"l": "berechnen", "t": "berechnen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche natürliche Zahl muss im Kästchen stehen? 3 · □² = 75"}, "o": {"wert": 5}, "h": "Mache zuerst das Malnehmen mit 3 rückgängig. Welche Zahl mit sich selbst malgenommen ergibt dann das Ergebnis?", "w": "3 · □² = 75, also □² = 75 : 3 = 25. Wegen 5 · 5 = 25 ist □ = 5. Probe: 3 · 5² = 3 · 25 = 75.", "form": "umkehren", "zaehlt": "ja", "r": 12561}, {"l": "berechnen", "t": "berechnen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ben berechnet 5 · 2³ − 3². Zeile 1: 2³ = 2 · 3 = 6, also ist 5 · 2³ = 5 · 6 = 30. Zeile 2: 3² = 3 · 3 = 9. Zeile 3: 30 − 9 = 21. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und schreibe jede Potenz als Produkt aus. Welche Zeile enthält zuerst einen Fehler?", "w": "2³ = 2 · 2 · 2 = 8, nicht 2 · 3. Richtig: 5 · 8 = 40 und 40 − 9 = 31. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12562}, {"l": "quadrat", "t": "berechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Rechne 15 · 15 schriftlich. Weg B: Schreibe den zweiten Faktor als 20 − 5 und rechne 15 · (20 − 5) = 15 · 20 − 15 · 5. Berechne 15² auf zwei Wegen."}, "o": {"wert": 225}, "h": "Bei Weg B rechnest du zwei einfachere Malaufgaben und ziehst ab.", "w": "Weg A schriftlich: 15 · 1 = 15, das sind 150 (eine Stelle nach links), dann 15 · 5 = 75; 150 + 75 = 225. Weg B: 15 · 20 = 300, 15 · 5 = 75, 300 − 75 = 225.", "form": "zwei_wege", "zaehlt": "ja", "r": 12563}, {"l": "quadrat", "t": "berechnen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Aus Plättchen wird ein Quadrat gelegt, 9 Plättchen lang und 9 Plättchen breit. Wie viele Plättchen liegen nicht am Rand, also im Inneren?"}, "o": {"wert": 49, "einheit": "Plättchen"}, "h": "Das Innere ist wieder ein Quadrat. Wie viele Plättchen lang ist es? Am Rand fehlt auf jeder Seite eine Reihe.", "w": "Innen bleibt ein Quadrat, das auf jeder Seite eine Reihe weniger hat: 9 − 2 = 7. 7² = 49 Plättchen. Kontrolle: Alle 9² = 81, Rand 4 · 9 − 4 = 32, 81 − 32 = 49.", "form": "bruecke", "zaehlt": "ja", "r": 12564}, {"l": "vertauschen", "t": "begriff", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für welche Hochzahl gilt 3 hoch □ = 81?"}, "o": {"wert": 4}, "h": "Wie oft muss die 3 als Faktor stehen, damit 81 herauskommt? Die Hochzahl sagt, wie oft die Basis als Faktor vorkommt.", "w": "3 · 3 = 9, 9 · 3 = 27, 27 · 3 = 81: Die 3 steht 4-mal als Faktor da, also 3⁴ = 81. Nicht verwechseln: 4³ ist 4 · 4 · 4 = 64. Probe: 3⁴ = 81.", "form": "umkehren", "zaehlt": "ja", "r": 12565}, {"l": "vertauschen", "t": "begriff", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mia vergleicht 3⁴ und 4³. Zeile 1: 3⁴ = 3 · 3 · 3 · 3 = 81. Zeile 2: 4³ = 4 · 4 · 4 = 64. Zeile 3: Also sind die beiden Potenzen gleich, weil nur Basis und Hochzahl getauscht sind. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich: Stimmt die Rechnung, und stimmt der Schluss daraus? Welche Zeile enthält zuerst einen Fehler?", "w": "81 und 64 sind verschieden. Beim Vertauschen von Basis und Hochzahl ändert sich der Wert im Allgemeinen. Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12566}, {"l": "zehner", "t": "zehner", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Schreibe 10⁵ als Zahl und multipliziere. Weg B: Überlege, wie viele Nullen man an 36 anhängt. Berechne 36 · 10⁵ auf zwei Wegen."}, "o": {"wert": 3600000}, "h": "Wie viele Nullen hat die Zahl 10⁵?", "w": "Weg A: 10⁵ = 100 000, 36 · 100 000 = 3 600 000. Weg B: Die Hochzahl 5 sagt: fünf Nullen anhängen. 36 mit fünf Nullen: 3 600 000.", "form": "zwei_wege", "zaehlt": "ja", "r": 12567}, {"l": "zehner", "t": "zehner", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Licht legt in einer Sekunde etwa 3 · 10⁵ Kilometer zurück. Wie viele Kilometer legt es in 10 Sekunden etwa zurück?"}, "o": {"wert": 3000000, "einheit": "km"}, "h": "Zehn Sekunden sind das Zehnfache. Was passiert mit einer Zehnerpotenz, wenn man mit 10 malnimmt?", "w": "In 10 Sekunden: 3 · 10⁵ · 10 = 3 · 10⁶ = 3 000 000 km. Die Strecke ist also etwa 3 000 000 km lang.", "form": "anwenden", "zaehlt": "ja", "r": 12568}, {"l": "negativ", "t": "negativ", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Schreibe (−3) · (−3) · (−3) und rechne Schritt für Schritt. Weg B: Bestimme das Vorzeichen daran, wie viele negative Faktoren es sind, und rechne dann 3³. Berechne (−3)³ auf zwei Wegen."}, "o": {"wert": -27}, "h": "Wie viele Faktoren (−3) gibt es? Wann ist ein Produkt negativ?", "w": "Weg A: (−3) · (−3) = 9, 9 · (−3) = −27. Weg B: Drei negative Faktoren, das Produkt ist negativ. 3³ = 27, also −27.", "form": "zwei_wege", "zaehlt": "ja", "r": 12569}, {"l": "negativ", "t": "negativ", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Lena berechnet −2⁴ + (−2)⁴. Zeile 1: −2⁴ bedeutet, dass 2⁴ negativ genommen wird: −2⁴ = −(2 · 2 · 2 · 2) = −16. Zeile 2: (−2)⁴ = (−2) · (−2) · (−2) · (−2) = −16. Zeile 3: Also ist die Summe −16 + (−16) = −32. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und zähle bei jedem Produkt die negativen Faktoren. Welche Zeile enthält zuerst einen Fehler?", "w": "Zwei negative Faktoren ergeben plus, vier ebenso: (−2)⁴ = 16. Richtig: −16 + 16 = 0. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12570}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Blätter eine Seerose an den ersten vier Tagen hat. Die Verdopplung geht jeden Tag so weiter. Wie viele Blätter hat die Seerose am Tag 9?", "grafik": {"typ": "tabelle", "kopf": ["Tag", "Blätter"], "zeilen": [["1", "1"], ["2", "2"], ["3", "4"], ["4", "8"]]}}, "o": {"wert": 256, "einheit": "Blätter"}, "h": "Erkenne das Muster in der Tabelle: Womit wird von Tag zu Tag malgenommen? Wie oft passiert das bis Tag 9?", "w": "Die Zahl wird jeden Tag mit 2 malgenommen. Von Tag 1 bis Tag 9 wird 8-mal verdoppelt: 2⁸ = 256 Blätter.", "form": "bruecke", "zaehlt": "ja", "r": 12571}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Bakterienkultur verdoppelt ihre Zahl jede Stunde. Nach 8 Stunden sind es 1 280 Bakterien. Wie viele Bakterien waren es am Anfang?"}, "o": {"wert": 5}, "h": "Wie viele Verdopplungen gab es? Mache sie rückgängig oder teile durch den Faktor.", "w": "In 8 Stunden wurde 8-mal verdoppelt, die Zahl wurde mit 2⁸ = 256 malgenommen. Am Anfang: 1 280 : 256 = 5. Probe: 5 · 256 = 1 280.", "form": "umkehren", "zaehlt": "ja", "r": 12572}]$auf$::jsonb),
    (44, 'zahlen.rechengesetze', 890, 28, $auf$[{"l": "punkt_strich", "t": "vorrang", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Zu 20 wird das Produkt aus 6 und 4 addiert. Danach wird 8 abgezogen. Welcher Term beschreibt das richtig?"}, "a": ["(20 + 6) · 4 − 8", "20 + 6 · 4 − 8", "20 + 6 · (4 − 8)", "20 + 6 + 4 − 8"], "o": {"index": 1}, "h": "Das Produkt aus 6 und 4 ist ein eigener Rechenschritt. Schreibe es ohne Klammern auf.", "w": "„Produkt aus 6 und 4“ ist 6 · 4. Dazu 20 addieren: 20 + 6 · 4. Dann 8 abziehen: 20 + 6 · 4 − 8. Punkt vor Strich passt hier ohne Klammern: 20 + 24 − 8 = 36.", "form": "bruecke", "zaehlt": "ja", "r": 12891}, {"l": "punkt_strich", "t": "vorrang", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Welche Zahl muss im Kästchen stehen, damit die Gleichung stimmt? 5 + □ · 4 = 49"}, "o": {"wert": 11}, "h": "Welche Rechenart wird in 5 + □ · 4 zuerst, welche zuletzt ausgeführt? Was folgt daraus für das Rückwärtsrechnen?", "w": "Zuletzt wird 5 addiert, also zuerst 5 abziehen: 49 − 5 = 44. Dann das Malnehmen mit 4 rückgängig machen: 44 : 4 = 11. Probe: 5 + 11 · 4 = 5 + 44 = 49.", "form": "umkehren", "zaehlt": "ja", "r": 12892}, {"l": "klammern", "t": "vorrang", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Rechne zuerst die Klammer aus. Weg B: Teile beide Zahlen in der Klammer einzeln durch 6 und ziehe die Ergebnisse voneinander ab. Berechne (48 − 12) : 6 auf zwei Wegen."}, "o": {"wert": 6}, "h": "Bei Weg B teilst du jede Zahl in der Klammer durch 6.", "w": "Weg A: 48 − 12 = 36, 36 : 6 = 6. Weg B: 48 : 6 = 8 und 12 : 6 = 2, 8 − 2 = 6. Beide Wege geben 6.", "form": "zwei_wege", "zaehlt": "ja", "r": 12893}, {"l": "klammern", "t": "vorrang", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Jan berechnet (30 − 6) · 3 − 4 · 2. Zeile 1: Zuerst die Klammer: 30 − 6 = 24. Zeile 2: Dann 24 · 3 = 72, also ist der Term gleich 72 − 4 · 2. Zeile 3: Von links nach rechts: 72 − 4 = 68, und 68 · 2 = 136. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich und frage bei jedem Rechenschritt: Ist das die richtige Reihenfolge? Welche Zeile enthält zuerst einen Fehler?", "w": "Punkt vor Strich: 4 · 2 = 8 muss vor dem Abziehen gerechnet werden. 72 − 8 = 64. Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12894}, {"l": "termaufbau", "t": "terme", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Term „das Dreifache der Summe aus einer Zahl und 4“ hat den Wert 27. Wie heißt die Zahl?"}, "o": {"wert": 5}, "h": "Schreibe den Term mit einem Kästchen für die Zahl auf. Was wird zuerst gerechnet, was zuletzt?", "w": "3 · (□ + 4) = 27, also □ + 4 = 27 : 3 = 9 und □ = 9 − 4 = 5. Probe: 3 · (5 + 4) = 3 · 9 = 27.", "form": "umkehren", "zaehlt": "ja", "r": 12895}, {"l": "termaufbau", "t": "terme", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Term A ist 6 + 4 · 5, Term B ist (6 + 4) · 5. Weg A: Berechne beide Terme und bilde den Unterschied. Weg B: Schreibe B als 6 · 5 + 4 · 5 und vergleiche mit A, ohne beide ganz auszurechnen. Um wie viel ist B größer als A?"}, "o": {"wert": 24}, "h": "Bei B steht 4 · 5 schon im Term, bei A auch. Was unterscheidet die beiden Terme noch?", "w": "Weg A: A = 6 + 20 = 26, B = 10 · 5 = 50, 50 − 26 = 24. Weg B: B = 6 · 5 + 4 · 5, A = 6 + 4 · 5. Der Unterschied ist 6 · 5 − 6 = 30 − 6 = 24.", "form": "zwei_wege", "zaehlt": "ja", "r": 12896}, {"l": "vorteil", "t": "gesetze", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche Zahl muss im Kästchen stehen, damit die Gleichung stimmt? 4 · □ · 25 = 1 700"}, "o": {"wert": 17}, "h": "Welche beiden der drei Faktoren ergeben zusammen eine runde Zahl? Rechne mit ihnen zuerst.", "w": "Die Faktoren darf man tauschen und verbinden: 4 · 25 = 100. Also 100 · □ = 1 700 und □ = 1 700 : 100 = 17. Probe: 4 · 17 · 25 = 68 · 25 = 1 700.", "form": "umkehren", "zaehlt": "ja", "r": 12897}, {"l": "vorteil", "t": "gesetze", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eva berechnet 4 · 37 · 25 geschickt. Zeile 1: Man darf die Faktoren vertauschen: 4 · 37 · 25 = 4 · 25 · 37. Zeile 2: 4 · 25 = 100. Zeile 3: 100 · 37 = 3 070. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe jede Zeile für sich und rechne jedes Zwischenergebnis nach. Welche Zeile enthält zuerst einen Fehler?", "w": "100 · 37 = 3 700, nicht 3 070. Richtig: 4 · 37 · 25 = 100 · 37 = 3 700. Der erste Fehler steht in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12898}, {"l": "differenz_summe", "t": "gesetze", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Mia hat 80 €. Sie kauft ein Buch für 25 € und ein Heft für 15 €. Welche Rechnung gibt an, wie viel Geld ihr übrig bleibt?"}, "a": ["80 − 25 + 15", "80 + (25 + 15)", "80 − 25 · 15", "80 − (25 + 15)"], "o": {"index": 3}, "h": "Beide Einkäufe kosten Geld. Was kostet beides zusammen? Wie kommst du von 80 € zum Rest?", "w": "Das Buch und das Heft kosten zusammen 25 € + 15 € = 40 €. Das Minus gilt für beide Ausgaben, deshalb steht die Summe in einer Klammer: 80 − (25 + 15) = 40 €.", "form": "bruecke", "zaehlt": "ja", "r": 12899}, {"l": "differenz_summe", "t": "gesetze", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Auf einem Konto sind 540 €. Es werden 175 € abgehoben, dann 25 € eingezahlt und danach 125 € abgehoben. Wie viel Euro sind danach auf dem Konto? Rechne geschickt: Fasse die beiden Abhebungen zusammen."}, "o": {"wert": 265, "einheit": "€"}, "h": "Welche Beträge verringern das Konto, welche erhöhen es? Was lässt sich zusammenfassen?", "w": "Abhebungen: 175 + 125 = 300. Einzahlung: 25. 540 − 300 + 25 = 265 €.", "form": "anwenden", "zaehlt": "ja", "r": 12900}, {"l": "verteilen", "t": "gesetze", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Rechne die Malaufgabe schriftlich. Weg B: Zerlege 27 in 20 + 7 und rechne 8 · 20 + 8 · 7. Berechne 8 · 27."}, "o": {"wert": 216}, "h": "Bei Weg B rechnest du zwei einfache Malaufgaben und addierst.", "w": "Weg A schriftlich: 8 · 7 = 56, schreibe 6 und merke 5; 8 · 2 = 16, dazu 5 ergibt 21; Ergebnis 216. Weg B: 8 · 20 = 160, 8 · 7 = 56, 160 + 56 = 216.", "form": "zwei_wege", "zaehlt": "ja", "r": 12901}, {"l": "verteilen", "t": "gesetze", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Nina berechnet 6 · 43 mit dem Verteilungsgesetz. Zeile 1: 43 = 40 + 3, also ist 6 · 43 = 6 · (40 + 3). Zeile 2: Verteilt: 6 · (40 + 3) = 6 · 40 + 3. Zeile 3: 6 · 40 + 3 = 240 + 3 = 243. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und rechne die Aufgabe zum Vergleich anders aus. Welche Zeile enthält zuerst einen Fehler?", "w": "Beide Summanden müssen mit 6 malgenommen werden: 6 · (40 + 3) = 6 · 40 + 6 · 3 = 240 + 18 = 258. Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12902}, {"l": "kopfrechnen", "t": "gesetze", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche Zahl ergibt mit 99 malgenommen 1 188? Tipp: 99 ist fast 100."}, "o": {"wert": 12}, "h": "Mit 100 malzunehmen ist leicht. Wie weit ist 1 188 von einem Vielfachen von 100 entfernt?", "w": "1 188 liegt knapp unter 1 200. 99 · 12 = 100 · 12 − 12 = 1 200 − 12 = 1 188. Die gesuchte Zahl ist 12.", "form": "umkehren", "zaehlt": "ja", "r": 12903}, {"l": "kopfrechnen", "t": "gesetze", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Hausmeister kauft 199 Schrauben zu je 6 Cent und 99 Dübel zu je 12 Cent. Wie viele Cent kosten beide Posten zusammen? Rechne geschickt im Kopf."}, "o": {"wert": 2382, "einheit": "Cent"}, "h": "Welche Zahlen liegen knapp unter einer runden Zahl? Was musst du nach dem Runden korrigieren?", "w": "Schrauben: 200 · 6 − 6 = 1 200 − 6 = 1 194 Cent. Dübel: 100 · 12 − 12 = 1 200 − 12 = 1 188 Cent. Zusammen 1 194 + 1 188 = 2 382 Cent.", "form": "anwenden", "zaehlt": "ja", "r": 12904}, {"l": "mal_ganz", "t": "ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Taucher sinkt jede Minute um 4 Meter. Um wie viele Meter hat sich seine Höhe nach 6 Minuten verändert? Gib die Veränderung mit Vorzeichen an (sinken ist negativ)."}, "o": {"wert": -24, "einheit": "m"}, "h": "Eine Minute bedeutet −4 Meter. Wie oft geschieht das?", "w": "Jede Minute ändert sich die Höhe um −4 m. Nach 6 Minuten: 6 · (−4) = −24 m.", "form": "anwenden", "zaehlt": "ja", "r": 12905}, {"l": "mal_ganz", "t": "ganz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Rechne von links nach rechts Schritt für Schritt. Weg B: Zähle die negativen Faktoren, bestimme so das Vorzeichen und multipliziere dann die Beträge. Berechne (−2) · (−5) · (−3) · 4 auf zwei Wegen."}, "o": {"wert": -120}, "h": "Bei Weg B: Ein negativer Faktor kehrt das Vorzeichen um. Wie oft passiert das?", "w": "Weg A: (−2) · (−5) = 10, 10 · (−3) = −30, −30 · 4 = −120. Weg B: Drei Faktoren sind negativ, das Ergebnis ist negativ. 2 · 5 · 3 · 4 = 120, also −120.", "form": "zwei_wege", "zaehlt": "ja", "r": 12906}, {"l": "geteilt_ganz", "t": "ganz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Rechne von links nach rechts. Weg B: Rechne zuerst (−4) · 3 und teile dann −84 durch das Ergebnis. Berechne (−84) : (−4) : 3 auf zwei Wegen."}, "o": {"wert": 7}, "h": "Bei Weg B ist der Teiler das Produkt aus (−4) und 3.", "w": "Weg A: (−84) : (−4) = 21, 21 : 3 = 7. Weg B: (−4) · 3 = −12, (−84) : (−12) = 7.", "form": "zwei_wege", "zaehlt": "ja", "r": 12907}, {"l": "geteilt_ganz", "t": "ganz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Durch welche ganze Zahl muss man −72 teilen, um 9 zu erhalten?"}, "o": {"wert": -8}, "h": "Das Ergebnis 9 ist positiv, die Zahl −72 ist negativ. Welches Vorzeichen muss der Teiler haben?", "w": "Aus −72 : □ = 9 folgt □ = (−72) : 9 = −8. Probe: (−72) : (−8) = 9.", "form": "umkehren", "zaehlt": "ja", "r": 12908}, {"l": "umkehraufgabe_mal", "t": "gleichungen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Teile −156 durch 12. Weg B: Zerlege −156 in −120 und −36 und überlege, womit man 12 jeweils malnehmen muss. Welche Zahl ergibt mit 12 malgenommen −156?"}, "o": {"wert": -13}, "h": "Bei Weg B: Womit musst du 12 malnehmen, um −120 zu erhalten? Und für −36?", "w": "Weg A: −156 : 12 = −13. Weg B: 12 · (−10) = −120, 12 · (−3) = −36. Zusammen 12 · (−13) = −156.", "form": "zwei_wege", "zaehlt": "ja", "r": 12909}, {"l": "umkehraufgabe_mal", "t": "gleichungen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst □ · (−5) = 40. Zeile 1: Die Umkehraufgabe heißt □ = 40 · (−5). Zeile 2: Also ist □ = −200. Zeile 3: Die gesuchte Zahl ist −200. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und mache mit dem Ergebnis die Probe in der Ausgangsgleichung. Welche Zeile enthält zuerst einen Fehler?", "w": "Malnehmen mit (−5) macht man durch Teilen durch (−5) rückgängig: □ = 40 : (−5) = −8. Probe: (−8) · (−5) = 40. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12910}, {"l": "ueberschlag", "t": "verfahren", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei einem Überschlag wird der erste Faktor 78 auf Zehner gerundet. Der Überschlag ergibt 6 000. Welche Zahl wurde für den zweiten Faktor eingesetzt?"}, "o": {"wert": 75}, "h": "Auf Zehner gerundet wird 78 zu einer glatten Zahl. Was musst du mit ihr malnehmen, um 6 000 zu erhalten?", "w": "78 wird zu 80 gerundet. 80 · □ = 6 000, also □ = 6 000 : 80 = 75.", "form": "umkehren", "zaehlt": "ja", "r": 12911}, {"l": "ueberschlag", "t": "verfahren", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Maja rechnet 487 · 62 mit dem Taschenrechner und ist unsicher, ob sie sich vertippt hat. Zur Auswahl stehen drei Ergebnisse. Welches Ergebnis kann stimmen? Prüfe mit einem Überschlag, den du selbst wählst, und mit der Endziffer."}, "a": ["30 194", "30 195", "31 194"], "o": {"index": 0}, "h": "Runde einen Faktor so, dass du genau sagen kannst, ob das Ergebnis größer oder kleiner sein muss. Welche Ziffer steht am Ende?", "w": "Die Endziffer des Produkts kommt von 7 · 2 = 14, also endet es auf 4. Damit scheidet 30 195 aus. Rundet man 487 auf 500, wird das Produkt größer: 487 · 62 ist kleiner als 500 · 62 = 31 000. Damit scheidet 31 194 aus. Es bleibt 30 194. Genau gerechnet: 487 · 62 = 30 194.", "form": "anwenden", "zaehlt": "ja", "r": 12912}, {"l": "schriftlich", "t": "verfahren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Teile schriftlich. Weg B: Zerlege 728 in 700 + 28 und teile beide Teile einzeln durch 14. Berechne 728 : 14."}, "o": {"wert": 52}, "h": "Bei Weg B: Wie oft passt 14 in 700? Wie oft in 28?", "w": "Weg A schriftlich: 72 : 14 = 5 Rest 2 (5 · 14 = 70); die 8 herunterholen: 28 : 14 = 2 Rest 0 (2 · 14 = 28); Ergebnis 52. Weg B: 700 : 14 = 50 und 28 : 14 = 2, zusammen 52. Probe: 52 · 14 = 728.", "form": "zwei_wege", "zaehlt": "ja", "r": 12913}, {"l": "schriftlich", "t": "verfahren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Tom rechnet schriftlich 346 · 27 und zerlegt: 27 = 20 + 7. Zeile 1: 346 · 20 = 692. Zeile 2: 346 · 7 = 2 422. Zeile 3: 692 + 2 422 = 3 114. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und überschlage die Teilprodukte. Welche Zeile enthält zuerst einen Fehler?", "w": "346 · 20 = 6 920 (346 · 2 = 692, dann eine Null anhängen). Richtig: 6 920 + 2 422 = 9 342. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12914}, {"l": "schriftlich_geteilt", "t": "verfahren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "275 Kinder sollen in Gruppen zu je 12 Kindern eingeteilt werden. Es werden so viele volle Gruppen gebildet wie möglich. Wie viele Kinder bleiben übrig?"}, "o": {"wert": 11, "einheit": "Kinder"}, "h": "Teile schriftlich. Was bleibt am Ende als Rest?", "w": "275 : 12 = 22 Rest 11, denn 22 · 12 = 264 und 275 − 264 = 11. Es bleiben 11 Kinder übrig.", "form": "anwenden", "zaehlt": "ja", "r": 12915}, {"l": "schriftlich_geteilt", "t": "verfahren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Teile schriftlich. Weg B: Ziehe von 3 128 zuerst 24 · 100 ab, dann so oft 24, wie es geht. Wie groß ist der Rest bei 3 128 : 24?"}, "o": {"wert": 8}, "h": "Bei Weg B: Nach 24 · 100 bleibt eine Zahl übrig. Wie viele 24er passen noch hinein?", "w": "Weg A schriftlich: 31 : 24 = 1 Rest 7 (1 · 24 = 24); die 2 herunterholen: 72 : 24 = 3 Rest 0 (3 · 24 = 72); die 8 herunterholen: 8 : 24 = 0 Rest 8. Ergebnis: 3 128 : 24 = 130 Rest 8. Weg B: 3 128 − 2 400 = 728. 728 − 30 · 24 = 728 − 720 = 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 12916}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Klasse mit 24 Kindern kauft ein Geschenk für 85 €. Jedes Kind gibt 3 €, die Schule gibt 20 € dazu. Weg A: Rechne aus, wie viel Geld insgesamt zusammenkommt, und ziehe den Preis ab. Weg B: Rechne zuerst aus, wie viel die Kinder zahlen müssten, wenn die Schule 20 € gibt, und vergleiche mit dem, was sie zahlen. Wie viel Geld bleibt übrig?"}, "o": {"wert": 7, "einheit": "€"}, "h": "Bei Weg B: Wie viel muss von den Kindern kommen, wenn die Schule schon 20 € gibt?", "w": "Weg A: 24 · 3 = 72, 72 + 20 = 92, 92 − 85 = 7. Weg B: 85 − 20 = 65 müssen die Kinder zahlen, sie zahlen 72. 72 − 65 = 7. Es bleiben 7 € übrig.", "form": "zwei_wege", "zaehlt": "ja", "r": 12917}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Im Zug sitzen 245 Fahrgäste. In A steigen 87 aus und 64 ein. In B steigen 120 aus. Pia berechnet, wie viele noch im Zug sitzen. Zeile 1: 245 − 87 = 168. Zeile 2: 168 + 64 = 232. Zeile 3: 232 − 120 = 112. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe jede Zeile für sich und rechne die Aufgaben mit der Gegenrechnung nach. Welche Zeile enthält zuerst einen Fehler?", "w": "245 − 87 = 158. Weiter: 158 + 64 = 222, 222 − 120 = 102. Es sitzen 102 Fahrgäste im Zug. Der erste Fehler steht in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12918}]$auf$::jsonb),
    (47, 'geometrie.grundbegriffe', 622, 14, $auf$[{"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Ein Punkt wird zweimal hintereinander um dieselbe Verschiebung bewegt: jedes Mal 2 Einheiten nach rechts und 3 Einheiten nach unten. Danach liegt er bei (3 | −4). Wo lag er am Anfang?"}, "a": ["(1 | −1)", "(7 | −10)", "(−1 | 2)", "(−1 | −10)"], "o": {"index": 2}, "h": "Welche Gesamtverschiebung ergeben die beiden Schritte? Wie kommst du von der Endlage zurück?", "w": "Zweimal 2 nach rechts und 3 nach unten sind zusammen 4 nach rechts und 6 nach unten. Rückwärts: 4 nach links und 6 nach oben. x: 3 − 4 = −1, y: −4 + 6 = 2. Der Punkt lag bei (−1 | 2). Probe: (−1 + 4 | 2 − 6) = (3 | −4).", "form": "umkehren", "zaehlt": "ja", "r": 12623}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Roboter steht im Punkt (−3 | 2). Er fährt zuerst 4 Einheiten nach rechts und dann 7 Einheiten nach unten. Weg A: Bestimme zuerst seine neue Position. Weg B: Vergleiche direkt, wie weit er nach unten fährt, mit seinem Abstand zur x-Achse am Start. Wie viele Einheiten ist er danach von der x-Achse entfernt?"}, "o": {"wert": 5, "einheit": "Einheiten"}, "h": "Welche Koordinate bestimmt den Abstand eines Punktes zur x-Achse? Wie ändert sie sich bei der Fahrt?", "w": "Weg A: Nach 4 nach rechts: (1 | 2). Nach 7 nach unten: (1 | 2 − 7) = (1 | −5). Der Abstand zur x-Achse ist |−5| = 5 Einheiten. Weg B: Am Start liegt er 2 Einheiten über der x-Achse, er fährt 7 nach unten, also 7 − 2 = 5 Einheiten darunter.", "form": "zwei_wege", "zaehlt": "ja", "r": 12624}, {"l": "strecken", "t": "strecken", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Weg verläuft waagrecht vom Punkt A(−4 | 1) zum Punkt B(5 | 1). Eine Einheit im Koordinatensystem entspricht 20 m. Weg A: Rechne mit den Koordinaten 5 − (−4). Weg B: Zähle die Einheiten von A bis zum Schnittpunkt (0 | 1) mit der y-Achse und von dort bis B. Wie lang ist der Weg in Metern?"}, "o": {"wert": 180, "einheit": "m"}, "h": "Der Weg schneidet die y-Achse im Punkt (0 | 1). Wie viele Einheiten sind es von A bis dorthin, wie viele von dort bis B?", "w": "Weg A: 5 − (−4) = 9 Einheiten. Weg B: Von A(−4 | 1) bis (0 | 1) sind es 4 Einheiten, von (0 | 1) bis B(5 | 1) sind es 5 Einheiten, zusammen 4 + 5 = 9 Einheiten. Der Weg ist 9 Einheiten lang: 9 · 20 m = 180 m.", "form": "zwei_wege", "zaehlt": "ja", "r": 12625}, {"l": "strecken", "t": "strecken", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle nennt drei Strecken, die alle waagrecht oder senkrecht verlaufen. Um wie viele Einheiten ist die längste Strecke länger als die kürzeste?", "grafik": {"typ": "tabelle", "kopf": ["Strecke", "Anfangspunkt", "Endpunkt"], "zeilen": [["[AB]", "A(−3 | 2)", "B(4 | 2)"], ["[CD]", "C(1 | −5)", "D(1 | 3)"], ["[EF]", "E(−6 | −1)", "F(−1 | −1)"]]}}, "o": {"wert": 3, "einheit": "Einheiten"}, "h": "Berechne zuerst die Länge jeder Strecke. Nur eine Koordinate ändert sich.", "w": "[AB]: 4 − (−3) = 7. [CD]: 3 − (−5) = 8. [EF]: −1 − (−6) = 5. Die längste ist 8, die kürzeste 5. 8 − 5 = 3.", "form": "bruecke", "zaehlt": "ja", "r": 12626}, {"l": "lagebeziehungen", "t": "lagebeziehungen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Gerade g verläuft von oben nach unten (parallel zur y-Achse). Sie wird um 5 Einheiten nach rechts verschoben und heißt danach h. Die Geraden g und h sind also parallel und haben den Abstand 5. Die Gerade h geht durch den Punkt (7 | 3). Welche x-Koordinate haben alle Punkte von g?"}, "o": {"wert": 2}, "h": "Um wie viel und in welche Richtung wurde g verschoben? Wie kommst du von h zu g zurück?", "w": "Alle Punkte von h haben die x-Koordinate 7, denn h geht durch (7 | 3) und verläuft von oben nach unten. g wurde um 5 nach rechts verschoben, also muss man um 5 nach links zurück: x = 7 − 5 = 2. Probe: 2 + 5 = 7, der Abstand von g und h ist 5.", "form": "umkehren", "zaehlt": "ja", "r": 12627}, {"l": "lagebeziehungen", "t": "lagebeziehungen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine waagrechte Hauptstraße liegt auf y = 2. Zwei Nebenstraßen stehen senkrecht auf ihr. Die eine geht durch den Punkt (5 | 2), die andere durch den Punkt (−3 | 2). Wie viele Einheiten sind die beiden Nebenstraßen voneinander entfernt?"}, "o": {"wert": 8, "einheit": "Einheiten"}, "h": "Beide Nebenstraßen sind senkrecht. Welche Koordinate legt ihre Lage fest?", "w": "Die Nebenstraßen liegen bei x = 5 und x = −3 und sind parallel. Ihr Abstand ist 5 − (−3) = 8 Einheiten.", "form": "anwenden", "zaehlt": "ja", "r": 12628}, {"l": "kreis_lage", "t": "kreis_lage", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Funkmast steht im Punkt M(2 | 3) und erreicht alle Orte, die höchstens 4 Einheiten von M entfernt sind. Wie viele der vier Häuser P(2 | 6), Q(7 | 3), R(−1 | 3) und S(2 | −2) werden erreicht? (Alle Häuser liegen auf einer waagrechten oder senkrechten Linie durch M.)"}, "o": {"wert": 2, "einheit": "Häuser"}, "h": "Bestimme für jedes Haus den Abstand zu M. Nur eine Koordinate ist anders.", "w": "P: 6 − 3 = 3 ≤ 4, erreicht. Q: 7 − 2 = 5 > 4, nicht erreicht. R: 2 − (−1) = 3 ≤ 4, erreicht. S: 3 − (−2) = 5 > 4, nicht erreicht. Es sind 2 Häuser.", "form": "anwenden", "zaehlt": "ja", "r": 12629}, {"l": "kreis_lage", "t": "kreis_lage", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Kreis um M(3 | 2) berührt von links die senkrechte Gerade x = 11. Welchen Radius hat der Kreis?"}, "o": {"wert": 8}, "h": "Welcher Punkt des Kreises liegt auf der Geraden? Wo liegt er im Vergleich zu M?", "w": "Der Berührpunkt ist (11 | 2). Der Radius ist der waagrechte Abstand von M: 11 − 3 = 8.", "form": "umkehren", "zaehlt": "ja", "r": 12630}, {"l": "winkelarten", "t": "winkelarten", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Der Minutenzeiger einer Uhr startet bei der 12 und dreht sich im Uhrzeigersinn bis zu einer Zahl auf dem Zifferblatt. Bis zu welcher Zahl hat er einen überstumpfen Winkel überstrichen?"}, "a": ["Bis zur 9", "Bis zur 3", "Bis zur 6", "Bis zur 12 nach einer ganzen Runde"], "o": {"index": 0}, "h": "Welcher Teil einer ganzen Runde ist bis zur Zahl geschafft? Überstumpf liegt zwischen gestreckt und Vollwinkel.", "w": "Von der 12 bis zur 3 ist es eine Vierteldrehung: 90°, ein rechter Winkel. Bis zur 6: halbe Drehung, 180°, gestreckt. Bis zur 9: Dreivierteldrehung, 270°, überstumpf. Bis zur 12 nach einer ganzen Runde: 360°, Vollwinkel.", "form": "bruecke", "zaehlt": "ja", "r": 12631}, {"l": "winkelarten", "t": "winkelarten", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Tür lässt sich von 0° bis 180° öffnen. Ein Feststeller hält sie bei jedem Vielfachen von 15° fest (0°, 15°, 30°, … bis 180°). Bei wie vielen dieser Einstellungen ist der Öffnungswinkel ein stumpfer Winkel?"}, "o": {"wert": 5, "einheit": "Einstellungen"}, "h": "Zwischen welchen beiden Gradzahlen liegen stumpfe Winkel? Welche Einstellungen des Feststellers fallen in diesen Bereich?", "w": "Stumpf heißt: größer als 90° und kleiner als 180°. Das trifft auf 105°, 120°, 135°, 150° und 165° zu, also 5 Einstellungen. 90° ist ein rechter Winkel, 180° ein gestreckter.", "form": "anwenden", "zaehlt": "ja", "r": 12632}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle beschreibt vier Vierecke A bis D. Welches Viereck ist eine Raute, die kein Quadrat ist?", "grafik": {"typ": "tabelle", "kopf": ["Viereck", "Alle vier Seiten gleich lang", "Vier rechte Winkel"], "zeilen": [["A", "ja", "ja"], ["B", "ja", "nein"], ["C", "nein", "ja"], ["D", "nein", "nein"]]}}, "a": ["Viereck A", "Viereck C", "Viereck D", "Viereck B"], "o": {"index": 3}, "h": "Eine Raute hat vier gleich lange Seiten. Ein Quadrat hat zusätzlich vier rechte Winkel.", "w": "Eine Raute hat vier gleich lange Seiten. Ein Quadrat hätte zusätzlich vier rechte Winkel. Gesucht ist also: gleich lange Seiten (ja), rechte Winkel (nein). Das ist Viereck B.", "form": "bruecke", "zaehlt": "ja", "r": 12633}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Beet hat die Form eines Rechtecks mit den Ecken A(−3 | −2), B(5 | −2), C(5 | 3) und D(−3 | 3). Eine Einheit entspricht 1 m. Wie viele Meter Zaun braucht man rund um das Beet?"}, "o": {"wert": 26, "einheit": "m"}, "h": "Wie lang sind die Seiten [AB] und [BC]? Eine Koordinate bleibt jeweils gleich.", "w": "[AB] hat die Länge 5 − (−3) = 8 m. [BC] hat die Länge 3 − (−2) = 5 m. Rundherum: 2 · (8 + 5) = 26 m.", "form": "anwenden", "zaehlt": "ja", "r": 12634}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Mia behauptet: „Jeder Punkt mit negativer x-Koordinate liegt unter der x-Achse.“ In der Tabelle stehen sechs Punkte. Bei wie vielen von ihnen zeigt sich, dass die Behauptung nicht stimmt?", "grafik": {"typ": "tabelle", "kopf": ["Punkt", "x-Koordinate", "y-Koordinate"], "zeilen": [["A", "−3", "4"], ["B", "−2", "−1"], ["C", "5", "−2"], ["D", "−6", "2"], ["E", "1", "3"], ["F", "−4", "−5"]]}}, "o": {"wert": 2, "einheit": "Punkte"}, "h": "Zu einem Gegenbeispiel gehört eine negative x-Koordinate, aber ein Punkt, der nicht unter der x-Achse liegt. Welche Punkte der Tabelle sind das?", "w": "Ein Gegenbeispiel hat x < 0 und liegt nicht unter der x-Achse, es gilt also x < 0 und y ≥ 0. Das trifft zu auf A(−3 | 4) und D(−6 | 2). B(−2 | −1) und F(−4 | −5) bestätigen die Behauptung, C(5 | −2) und E(1 | 3) haben ein positives x. Es sind 2 Punkte.", "form": "bruecke", "zaehlt": "ja", "r": 12635}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "transfer", "y": "auswahl", "f": {"text": "Tom behauptet: „Jedes Viereck mit vier gleich langen Seiten ist ein Quadrat.“ Welche Figur zeigt, dass Tom nicht recht hat?"}, "a": ["Ein Quadrat mit 5 cm Seitenlänge", "Eine Raute mit 5 cm Seitenlänge und den Winkeln 60° und 120°", "Ein Rechteck mit den Seiten 3 cm und 5 cm", "Ein Parallelogramm mit den Seiten 4 cm und 6 cm"], "o": {"index": 1}, "h": "Ein Gegenbeispiel muss die Voraussetzung (vier gleich lange Seiten) erfüllen, aber trotzdem kein Quadrat sein.", "w": "Gesucht ist ein Viereck mit vier gleich langen Seiten, das kein Quadrat ist: Die Raute mit den Winkeln 60° und 120° hat vier gleich lange Seiten, aber keine rechten Winkel.", "form": "anwenden", "zaehlt": "ja", "r": 12636}]$auf$::jsonb),
    (49, 'geometrie.winkel', 559, 14, $auf$[{"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Ziehe 62° von 180° ab. Weg B: Ergänze 62° zuerst zu einem rechten Winkel und füge dann noch einen rechten Winkel hinzu. Welcher Winkel ergänzt 62° zu einem gestreckten Winkel?"}, "o": {"wert": 118, "einheit": "°"}, "h": "Ein gestreckter Winkel besteht aus zwei rechten Winkeln.", "w": "Weg A: 180° − 62° = 118°. Weg B: 90° − 62° = 28° bis zum rechten Winkel, dazu noch 90°: 28° + 90° = 118°.", "form": "zwei_wege", "zaehlt": "ja", "r": 12560}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Winkel wird um 35° vergrößert. Der vergrößerte Winkel ergänzt einen Winkel von 48° zu einem gestreckten Winkel. Wie groß war der Winkel vor der Vergrößerung?"}, "o": {"wert": 97, "einheit": "°"}, "h": "Welcher Winkel hängt direkt mit den 48° zusammen? Welcher Schritt kam zuletzt?", "w": "Der vergrößerte Winkel ist 180° − 48° = 132°. Vor der Vergrößerung war er 35° kleiner: 132° − 35° = 97°. Probe: 97° + 35° = 132°, 132° + 48° = 180°.", "form": "umkehren", "zaehlt": "ja", "r": 12561}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei gerade Straßen kreuzen sich. Einer der vier Winkel zwischen den Straßen beträgt 38°. Wie groß ist der größte der vier Winkel?"}, "o": {"wert": 142, "einheit": "°"}, "h": "Je zwei benachbarte Winkel ergeben zusammen einen gestreckten Winkel. Gegenüberliegende Winkel sind gleich groß.", "w": "Der Nachbarwinkel von 38° ist 180° − 38° = 142°. Die anderen beiden Winkel sind 38° und 142° (gegenüberliegende Winkel sind gleich). Der größte ist 142°.", "form": "anwenden", "zaehlt": "ja", "r": 12562}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel ist 24° größer als sein Nachbarwinkel. Weg A: Nenne den kleineren Winkel w und löse w + (w + 24°) = 180°. Weg B: Wären beide Winkel gleich groß, hätte jeder 90°. Überlege, wie viel Grad vom einen zum anderen wandern müssen, damit der Unterschied 24° beträgt. Wie groß ist der größere Winkel?"}, "o": {"wert": 102, "einheit": "°"}, "h": "Wie groß ist die Summe zweier Nachbarwinkel? Was geschieht mit dem Unterschied, wenn ein Winkel kleiner und der andere um genauso viel größer wird?", "w": "Weg A: 2w + 24° = 180°, also 2w = 156°, w = 78°. Der größere Winkel ist 78° + 24° = 102°. Weg B: Von 90° und 90° wandern 12° vom einen zum anderen: 78° und 102°. Der Unterschied ist 24°. Probe: 102° + 78° = 180°.", "form": "zwei_wege", "zaehlt": "ja", "r": 12563}, {"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Ein Kreisdiagramm zeigt, welches Obst eine Klasse am liebsten mag. Die Tabelle nennt die Winkel von drei Sektoren. Der übrige Teil des Kreises heißt „Sonstiges“. Wie groß ist der Winkel des Sektors „Sonstiges“?", "grafik": {"typ": "tabelle", "kopf": ["Obst", "Winkel im Kreisdiagramm"], "zeilen": [["Äpfel", "120°"], ["Bananen", "90°"], ["Trauben", "45°"]]}}, "o": {"wert": 105, "einheit": "°"}, "h": "Alle Sektoren zusammen füllen den Vollwinkel. Wie viel Grad sind schon vergeben?", "w": "Die drei genannten Sektoren sind zusammen 120° + 90° + 45° = 255° groß. Der Rest bis 360° ist 360° − 255° = 105°.", "form": "bruecke", "zaehlt": "ja", "r": 12564}, {"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine runde Torte wird so aufgeschnitten: Ein Stück hat an der Spitze 90°, ein Stück hat 60°. Der Rest wird in 5 gleich große Stücke geschnitten. Wie groß ist die Spitze eines dieser Reststücke?"}, "o": {"wert": 42, "einheit": "°"}, "h": "Wie viel Grad bleiben nach den beiden ersten Stücken übrig? Wie teilst du das auf?", "w": "Die ersten beiden Stücke haben 90° + 60° = 150°. Es bleiben 360° − 150° = 210°. Auf 5 Stücke verteilt: 210° : 5 = 42°.", "form": "anwenden", "zaehlt": "ja", "r": 12565}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Betrachte den Minutenzeiger einer Uhr und eine Zeitspanne von 20 Minuten. Weg A: Bestimme zuerst, um wie viel Grad er sich in 1 Minute dreht, und rechne dann mal 20. Weg B: Zwischen zwei Zahlen auf dem Zifferblatt liegen 5 Minuten. Bestimme den Winkel zwischen zwei Zahlen und überlege, wie oft 5 Minuten in 20 Minuten passen. Gib an, um wie viel Grad sich der Minutenzeiger in 20 Minuten dreht."}, "o": {"wert": 120, "einheit": "°"}, "h": "Eine ganze Stunde sind 360° für den Minutenzeiger. Wie viele Minuten hat eine Stunde, wie viele Zahlen das Zifferblatt?", "w": "Weg A: In 60 Minuten dreht er sich um 360°, in 1 Minute um 6°. 20 · 6° = 120°. Weg B: Zwischen zwei Zahlen liegen 5 Minuten und 360° : 12 = 30°. 20 Minuten sind 4 solche Schritte, 4 · 30° = 120°.", "form": "zwei_wege", "zaehlt": "ja", "r": 12566}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Die Uhr am Bahnhof zeigt 2:50 Uhr. Der Stundenzeiger dreht sich in einer Stunde um 30°, der Minutenzeiger in einer Stunde um 360°. Beide Zeiger starten um 12:00 Uhr bei der 12. Wie groß ist der kleinere Winkel zwischen Stundenzeiger und Minutenzeiger?"}, "o": {"wert": 145, "einheit": "°"}, "h": "Beide Zeiger bewegen sich weiter, auch der kurze. Rechne für jeden Zeiger den Winkel von der 12 aus.", "w": "Der Minutenzeiger hat nach 50 Minuten 50 · 6° = 300° zurückgelegt. Der Stundenzeiger hat 2 · 30° = 60° und in 50 Minuten noch 50 · 0,5° = 25° mehr, also 85°. Der Unterschied ist 300° − 85° = 215°. Das ist größer als 180°, der kleinere Winkel ist 360° − 215° = 145°.", "form": "anwenden", "zaehlt": "ja", "r": 12567}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Roboter schaut nach Norden. Er dreht sich zuerst um 90° im Uhrzeigersinn und danach um 180° gegen den Uhrzeigersinn. In welche Richtung schaut er danach?"}, "a": ["Osten", "Westen", "Süden", "Norden"], "o": {"index": 1}, "h": "Zeichne dir eine Windrose. Im Uhrzeigersinn geht es von Norden nach Osten.", "w": "Norden, 90° im Uhrzeigersinn: Osten. Von Osten 180° gegen den Uhrzeigersinn: Westen.", "form": "anwenden", "zaehlt": "ja", "r": 12568}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Schiff dreht sich um 90° nach rechts, dann um 45° nach links und danach um 180° nach rechts. Weg A: Rechne mit Grad: Bestimme nach jeder Drehung die Gesamtdrehung. Weg B: Zähle auf der Windrose in Schritten von 45° (Abstand zweier Nachbarrichtungen): Wie viele Schritte sind es nach rechts, wie viele nach links? Gib die resultierende Drehung (netto nach rechts) in Grad an."}, "o": {"wert": 225, "einheit": "°"}, "h": "Eine Drehung nach links macht eine Drehung nach rechts zum Teil rückgängig.", "w": "Weg A: Nach der 1. Drehung 90° rechts, nach der 2. 45° rechts, nach der 3. 225° rechts. Weg B: 90° sind 2 Schritte nach rechts, 45° ist 1 Schritt nach links, 180° sind 4 Schritte nach rechts. Insgesamt 2 − 1 + 4 = 5 Schritte nach rechts. 5 · 45° = 225°.", "form": "zwei_wege", "zaehlt": "ja", "r": 12569}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zeichnung zeigt ein Rechteck ABCD. Von der Ecke A gehen die Strecken [AE] und [AF] aus. Eingetragen sind ∠BAE = 25° und ∠FAD = 30°. Wie groß ist ∠EAF?", "grafik": {"typ": "figur", "punkte": {"A": [0, 0], "B": [7, 0], "C": [7, 7], "D": [0, 7], "E": [7, 3.264], "F": [4.041, 7]}, "flaeche": ["A", "B", "C", "D"], "linien": [["A", "B"], ["B", "C"], ["C", "D"], ["D", "A"], ["A", "E"], ["A", "F"]], "winkel": [["A", "B", "E", "25°"], ["A", "F", "D", "30°"], ["A", "E", "F", "?"]]}}, "o": {"wert": 35, "einheit": "°"}, "h": "Wie groß ist der Winkel bei A im Rechteck? Welche drei Winkel füllen ihn zusammen aus?", "w": "Der Eckwinkel des Rechtecks bei A ist 90°. Er besteht aus ∠BAE = 25°, ∠EAF und ∠FAD = 30°. Also ∠EAF = 90° − 25° − 30° = 35°. Probe: 25° + 35° + 30° = 90°.", "form": "bruecke", "zaehlt": "ja", "r": 12570}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Rechteck gehen von einer Ecke aus zwei Strecken, die den rechten Winkel in drei Teile teilen. Der mittlere Teil ist 10° größer als der kleinste, der größte Teil ist 10° größer als der mittlere. Weg A: Nenne den kleinsten Teil k und löse k + (k + 10°) + (k + 20°) = 90°. Weg B: Wären alle drei Teile gleich groß, hätte jeder 30°. Überlege, wie der mittlere Teil dazu liegt und wie viel der größte Teil mehr hat. Gib die Größe des größten Teils an."}, "o": {"wert": 40, "einheit": "°"}, "h": "Wie groß wäre jeder Teil bei gleich großen Teilen? Was passiert mit den Unterschieden von 10° nach unten und nach oben?", "w": "Weg A: 3k + 30° = 90°, also 3k = 60° und k = 20°. Die Teile sind 20°, 30° und 40°. Der größte Teil ist 40°. Weg B: Der kleinste Teil ist 10° kleiner als der mittlere, der größte 10° größer. Die Unterschiede gleichen sich aus, der mittlere Teil ist also 90° : 3 = 30° groß und der größte 30° + 10° = 40°. Probe: 20° + 30° + 40° = 90°.", "form": "zwei_wege", "zaehlt": "ja", "r": 12571}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Tim behauptet: „Addiert man zwei spitze Winkel, ist die Summe immer ein stumpfer Winkel.“ Betrachte die Paare 20° + 40°, 50° + 60°, 80° + 70°, 30° + 30°, 60° + 85° und 45° + 45°. Weg A: Rechne jede Summe aus und ordne sie ein. Weg B: Ergänze den ersten Winkel zu 90° und vergleiche mit dem zweiten Winkel. Gib die Zahl der Paare an, bei denen die Behauptung stimmt."}, "o": {"wert": 3, "einheit": "Paare"}, "h": "Ein stumpfer Winkel ist größer als 90° und kleiner als 180°. Ist 90° selbst stumpf?", "w": "Weg A: Die Summen sind 60°, 110°, 150°, 60°, 145° und 90°. Stumpf, also größer als 90° und kleiner als 180°, sind 110°, 150° und 145°. Die Summe 90° ist ein rechter Winkel, 60° ist spitz. Weg B: Bei 20° fehlen 70° bis 90° und 40° ist weniger, die Summe bleibt unter 90°. Bei 50° fehlen 40° und 60° ist mehr: stumpf. Bei 80° fehlen 10° und 70° ist mehr: stumpf. Bei 30° fehlen 60° und 30° ist weniger: spitz. Bei 60° fehlen 30° und 85° ist mehr: stumpf. Bei 45° fehlen 45° und 45° ist genau so viel: rechter Winkel. Zwei spitze Winkel ergeben immer weniger als 180°. Es sind 3 Paare.", "form": "zwei_wege", "zaehlt": "ja", "r": 12572}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Tim behauptet: „Wenn man einen Winkel verdoppelt und dann 20° dazuzählt, entsteht ein gestreckter Winkel.“ Für welchen Winkel stimmt Tims Aussage?"}, "o": {"wert": 80, "einheit": "°"}, "h": "Wie ist der gestreckte Winkel entstanden? Welcher Schritt war der letzte?", "w": "Rückwärts: Erst 20° abziehen: 180° − 20° = 160°. Dann das Verdoppeln rückgängig machen: 160° : 2 = 80°. Probe: 2 · 80° + 20° = 180°.", "form": "umkehren", "zaehlt": "ja", "r": 12573}]$auf$::jsonb),
    (50, 'groessen.einheiten', 648, 16, $auf$[{"l": "schaetzen", "t": "schaetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Treppenstufe ist etwa 20 cm hoch. Weg A: Rechne 9 m in cm um und teile durch die Höhe einer Stufe. Weg B: Überlege, wie viele Stufen auf 1 m kommen, und rechne damit weiter. Wie viele Stufen braucht eine Treppe für einen Höhenunterschied von 9 m ungefähr?"}, "o": {"wert": 45, "einheit": "Stufen"}, "h": "Wie viele Stufen von 20 cm sind zusammen 1 m hoch?", "w": "Weg A: 9 m = 900 cm, 900 : 20 = 45. Weg B: 1 m = 100 cm, das sind 100 : 20 = 5 Stufen. Für 9 m sind es 9 · 5 = 45 Stufen.", "form": "zwei_wege", "zaehlt": "ja", "r": 12649}, {"l": "schaetzen", "t": "schaetzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "auswahl", "f": {"text": "Ein Kind geht einen 150 m langen Weg im Durchschnitt in 250 Schritten, ein Erwachsener braucht für denselben Weg im Durchschnitt 200 Schritte. Um etwa wie viel ist ein Schritt des Erwachsenen im Durchschnitt länger als ein Schritt des Kindes?"}, "a": ["20 cm", "2 cm", "2 m"], "o": {"index": 0}, "h": "Für 150 m braucht das Kind mehr Schritte als der Erwachsene. Um welchen Bruchteil mehr, und was folgt daraus für die Schrittlängen?", "w": "Größenordnung: Das Kind braucht für denselben Weg ein Viertel mehr Schritte. Der Erwachsenenschritt ist deshalb rund ein Viertel einer Kinderschrittlänge länger. Von 2 cm, 20 cm und 2 m passt 20 cm. Genau: 150 m = 15 000 cm. Kind: 15 000 cm : 250 = 60 cm je Schritt. Erwachsener: 15 000 cm : 200 = 75 cm je Schritt. Unterschied: 75 cm − 60 cm = 15 cm. Probe: 200 · 75 cm = 15 000 cm = 150 m.", "form": "umkehren", "zaehlt": "ja", "r": 12650}, {"l": "laenge", "t": "laenge", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Band wurde um 135 cm gekürzt. Jetzt ist es 2 m 15 cm lang. Wie lang war es vorher in cm?"}, "o": {"wert": 350, "einheit": "cm"}, "h": "Mache das Kürzen rückgängig. Rechne zuerst die jetzige Länge in cm.", "w": "Jetzt: 2 m 15 cm = 215 cm. Vorher war das Band um 135 cm länger: 215 + 135 = 350 cm.", "form": "umkehren", "zaehlt": "ja", "r": 12651}, {"l": "laenge", "t": "laenge", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Rechne 3 km in m um und addiere 40 m. Weg B: Schreibe die Länge zuerst als Dezimalzahl in km und rechne dann in m um. Wie viele Meter sind 3 km 40 m?"}, "o": {"wert": 3040, "einheit": "m"}, "h": "Wie viele Meter hat 1 km? Wie schreibt man 40 m in km?", "w": "Weg A: 3 km = 3 000 m, dazu 40 m: 3 040 m. Weg B: 40 m = 0,04 km, also 3 km 40 m = 3,04 km. 3,04 · 1 000 = 3 040 m.", "form": "zwei_wege", "zaehlt": "ja", "r": 12652}, {"l": "masse", "t": "masse", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt die Zutaten für einen Kuchen in verschiedenen Einheiten. Wie viele Kilogramm wiegen alle drei Zutaten zusammen?", "grafik": {"typ": "tabelle", "kopf": ["Zutat", "Menge"], "zeilen": [["Mehl", "2 kg 500 g"], ["Zucker", "750 g"], ["Butter", "250 g"]]}}, "o": {"wert": 3.5, "einheit": "kg"}, "h": "Schreibe alle Mengen in derselben Einheit, bevor du addierst.", "w": "In g: 2 kg 500 g = 2 500 g, dazu 750 g und 250 g: 2 500 + 750 + 250 = 3 500 g = 3,5 kg.", "form": "bruecke", "zaehlt": "ja", "r": 12653}, {"l": "masse", "t": "masse", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Lastenaufzug trägt höchstens 1 t. Auf ihm stehen schon 7 Kisten zu je 120 kg. Wie viele weitere Kisten zu je 25 kg dürfen höchstens noch dazu gestellt werden?"}, "o": {"wert": 6, "einheit": "Kisten"}, "h": "Rechne 1 t in kg um. Wie viele kg sind noch frei?", "w": "1 t = 1 000 kg. Schon da: 7 · 120 = 840 kg. Noch frei: 160 kg. 160 : 25 = 6,4, es passen also höchstens 6 Kisten.", "form": "anwenden", "zaehlt": "ja", "r": 12654}, {"l": "zeit", "t": "zeit", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Der Fahrplan zeigt Abfahrt und Ankunft eines Zuges. Wie viele Minuten dauert die Fahrt?", "grafik": {"typ": "tabelle", "kopf": ["Halt", "Uhrzeit"], "zeilen": [["Abfahrt Hauptbahnhof", "8:47 Uhr"], ["Ankunft Altstadt", "10:12 Uhr"]]}}, "o": {"wert": 85, "einheit": "min"}, "h": "Wie viele Minuten sind es bis 9:00 Uhr? Dann weiter bis 10:12 Uhr.", "w": "Von 8:47 Uhr bis 9:00 Uhr sind es 13 Minuten, von 9:00 Uhr bis 10:12 Uhr sind es 72 Minuten. Zusammen 13 + 72 = 85 Minuten.", "form": "bruecke", "zaehlt": "ja", "r": 12655}, {"l": "zeit", "t": "zeit", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Weg A: Ergänze bis zur vollen Stunde und zähle dann weiter. Weg B: Rechne beide Uhrzeiten in Minuten seit Mitternacht um und ziehe ab. Wie viele Minuten liegen zwischen 14:35 Uhr und 17:10 Uhr?"}, "o": {"wert": 155, "einheit": "min"}, "h": "Wie viele Minuten sind es von 14:35 Uhr bis 15:00 Uhr?", "w": "Weg A: 14:35 bis 15:00 sind 25 min, 15:00 bis 17:00 sind 120 min, 17:00 bis 17:10 sind 10 min: 155 min. Weg B: 17:10 Uhr = 1 030 min, 14:35 Uhr = 875 min. 1 030 − 875 = 155.", "form": "zwei_wege", "zaehlt": "ja", "r": 12656}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Wanderweg ist 12,5 km lang. Marie ist schon 4 800 m gegangen. Wie viele Meter muss sie noch gehen?"}, "o": {"wert": 7700, "einheit": "m"}, "h": "Rechne beide Längen in dieselbe Einheit um, bevor du abziehst.", "w": "12,5 km = 12 500 m. Noch zu gehen: 12 500 − 4 800 = 7 700 m.", "form": "anwenden", "zaehlt": "ja", "r": 12657}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Tim rechnet: „3,08 kg sind 3 kg 8 g, also 3 008 g.“ Prüfe seine Umrechnung. Weg A: Rechne 3,08 · 1 000. Weg B: Schreibe 3,08 kg mit drei Stellen hinter dem Komma (3,080 kg) und lies kg und g ab. Wie viele Gramm sind 3,08 kg wirklich?"}, "o": {"wert": 3080, "einheit": "g"}, "h": "Ein Gramm ist ein Tausendstel eines Kilogramms. Welche Stellen hinter dem Komma gehören zu den Gramm?", "w": "Weg A: 3,08 · 1 000 = 3 080 g. Weg B: 3,08 kg = 3,080 kg. Vor dem Komma stehen die 3 kg, die drei Stellen dahinter (080) sind die Gramm: 3 kg 80 g = 3 000 g + 80 g = 3 080 g.", "form": "zwei_wege", "zaehlt": "ja", "r": 12658}, {"l": "rechnen", "t": "rechnen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Von einem 5 m langen Seil werden zwei gleich lange Stücke abgeschnitten. Übrig bleibt ein Rest von 1 m 20 cm. Wie lang ist jedes abgeschnittene Stück in cm?"}, "o": {"wert": 190, "einheit": "cm"}, "h": "Wie viel Seil wurde insgesamt abgeschnitten? Beide Längen müssen dazu in derselben Einheit stehen.", "w": "5 m = 500 cm und 1 m 20 cm = 120 cm. Abgeschnitten wurden 500 cm − 120 cm = 380 cm. Das sind zwei gleich lange Stücke: 380 cm : 2 = 190 cm. Probe: 2 · 190 cm + 120 cm = 500 cm.", "form": "umkehren", "zaehlt": "ja", "r": 12659}, {"l": "rechnen", "t": "rechnen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Vier Freunde teilen sich die Rechnung von 46,80 € und zusätzlich 2 € Trinkgeld gleichmäßig auf. Wie viel Euro zahlt jeder?"}, "o": {"wert": 12.2, "einheit": "€"}, "h": "Wie viel kostet alles zusammen? Wie teilst du das auf vier Personen auf?", "w": "Insgesamt: 46,80 € + 2 € = 48,80 €. Jeder zahlt 48,80 € : 4 = 12,20 €.", "form": "anwenden", "zaehlt": "ja", "r": 12660}, {"l": "massstab", "t": "massstab", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf einer Karte mit dem Maßstab 1 : 25 000 sind zwei Orte 8 cm voneinander entfernt. Weg A: Rechne 8 cm mal 25 000 und wandle um. Weg B: Bestimme zuerst, wie viele Meter 1 cm auf der Karte in Wirklichkeit sind, und rechne damit. Wie viele Kilometer liegen sie in Wirklichkeit auseinander?"}, "o": {"wert": 2, "einheit": "km"}, "h": "Wie viele cm sind 1 km? Wie viele m sind 25 000 cm?", "w": "Weg A: 8 · 25 000 cm = 200 000 cm = 2 000 m = 2 km. Weg B: 1 cm auf der Karte sind 25 000 cm = 250 m. 8 · 250 m = 2 000 m = 2 km.", "form": "zwei_wege", "zaehlt": "ja", "r": 12661}, {"l": "massstab", "t": "massstab", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Auf einer Wanderkarte mit dem Maßstab 1 : 50 000 ist der Weg zur Hütte 14 cm lang. Eine Gruppe wandert 4 km pro Stunde. Wie viele Minuten braucht sie für den Weg?"}, "o": {"wert": 105, "einheit": "min"}, "h": "Welche Größen brauchst du, um aus Weglänge und Tempo eine Zeit zu bekommen? Auf welche Einheiten musst du achten?", "w": "14 · 50 000 cm = 700 000 cm = 7 km. 7 km : 4 km/h = 1,75 h. 1,75 h = 105 min.", "form": "anwenden", "zaehlt": "ja", "r": 12662}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle nennt fünf Beispiele mit einer Größenangabe. Bei wie vielen Beispielen ist die Angabe nicht realistisch?", "grafik": {"typ": "tabelle", "kopf": ["Beispiel", "Angabe"], "zeilen": [["Schulheft", "21 cm lang"], ["Bleistift", "5 kg schwer"], ["Klassenzimmer", "3 m hoch"], ["Apfel", "150 g schwer"], ["Kind mit 10 Jahren", "14 m groß"]]}}, "o": {"wert": 2, "einheit": "Angaben"}, "h": "Vergleiche mit etwas, das du kennst: Wie lang ist ein Lineal? Wie schwer ist ein Apfel?", "w": "Ein Bleistift mit 5 kg wäre so schwer wie fünf Packungen Zucker, er wiegt nur wenige Gramm. Ein Kind mit 14 m wäre höher als ein Haus. Die anderen Angaben passen: Heft 21 cm, Zimmerhöhe 3 m, Apfel 150 g. Es sind 2 Angaben.", "form": "bruecke", "zaehlt": "ja", "r": 12663}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "auswahl", "f": {"text": "Ein Zug kommt um 15:12 Uhr an. Die Fahrt hat 2,5 Stunden gedauert. Tim sagt: „Er ist um 12:22 Uhr abgefahren.“ Welche Abfahrtszeit ist richtig?"}, "a": ["12:42 Uhr", "17:42 Uhr", "12:12 Uhr", "12:22 Uhr"], "o": {"index": 0}, "h": "Rechne 2,5 Stunden in Stunden und Minuten um. Gehe dann rückwärts von der Ankunftszeit und prüfe Tims Angabe.", "w": "2,5 h = 2 h 30 min. Rückwärts von 15:12 Uhr: 2 h zurück ergibt 13:12 Uhr, weitere 30 min zurück ergibt 12:42 Uhr. Probe: 12:42 Uhr + 2 h 30 min = 15:12 Uhr.", "form": "umkehren", "zaehlt": "ja", "r": 12664}]$auf$::jsonb),
    (51, 'messen.flaechen', 588, 14, $auf$[{"l": "einheitsquadrate", "t": "einheitsquadrate", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rechteck besteht aus 6 Reihen mit je 12 Einheitsquadraten. Weg A: Rechne 6 · 12. Weg B: Teile das Rechteck in zwei gleich große Hälften, die jeweils 6 Quadrate breit sind, bestimme die Zahl in einer Hälfte und verdopple. Wie viele Einheitsquadrate sind es?"}, "o": {"wert": 72, "einheit": "Quadrate"}, "h": "Wie viele Quadrate sind eine Hälfte breit? Wie viele Reihen hat sie?", "w": "Weg A: 6 · 12 = 72. Weg B: Jede Hälfte ist 6 Quadrate breit und hat 6 Reihen: 6 · 6 = 36. Zwei Hälften: 2 · 36 = 72.", "form": "zwei_wege", "zaehlt": "ja", "r": 12589}, {"l": "einheitsquadrate", "t": "einheitsquadrate", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Terrasse ist 6 m lang und 4 m breit. Sie wird lückenlos mit quadratischen Platten von 50 cm Seitenlänge belegt. Nur ein rechteckiges Beet von 3 m Länge und 1 m Breite bleibt frei. Das Beet liegt in einer Ecke, seine Ränder verlaufen entlang der Plattenreihen. Wie viele Platten braucht man?"}, "o": {"wert": 84, "einheit": "Platten"}, "h": "Welche Einheit müssen Terrasse, Beet und Platte gemeinsam haben? Was wird nicht belegt?", "w": "In 1 m passen 2 Platten. Terrasse: 6 · 2 = 12 Platten in der Länge, 4 · 2 = 8 in der Breite, zusammen 12 · 8 = 96 Platten. Beet: 3 · 2 = 6 mal 1 · 2 = 2, also 12 Platten. 96 − 12 = 84 Platten. Kontrolle: 24 m² − 3 m² = 21 m², auf 1 m² passen 4 Platten: 21 · 4 = 84.", "form": "anwenden", "zaehlt": "ja", "r": 12590}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt fünf Rechtecke, die alle den Umfang 20 m haben. Wie groß ist der Flächeninhalt des Rechtecks mit der größten Fläche? Gib die Fläche in m² an.", "grafik": {"typ": "tabelle", "kopf": ["Länge in m", "Breite in m"], "zeilen": [["9", "1"], ["8", "2"], ["7", "3"], ["6", "4"], ["5", "5"]]}}, "o": {"wert": 25, "einheit": "m²"}, "h": "Berechne die Fläche jedes Rechtecks aus Länge mal Breite und vergleiche.", "w": "Flächen: 9 · 1 = 9, 8 · 2 = 16, 7 · 3 = 21, 6 · 4 = 24, 5 · 5 = 25. Die größte Fläche hat das Quadrat mit 25 m².", "form": "bruecke", "zaehlt": "ja", "r": 12591}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein rechteckiger Spielplatz hat den Umfang 36 m und ist doppelt so lang wie breit. Wie groß ist seine Fläche in m²?"}, "o": {"wert": 72, "einheit": "m²"}, "h": "Wie hängen Länge und Breite zusammen? Was sagt der Umfang über Länge plus Breite?", "w": "Länge + Breite = 36 : 2 = 18 m. Das sind 3 gleiche Teile (Breite + zweimal Breite), ein Teil ist 6 m. Breite 6 m, Länge 12 m. Fläche: 12 · 6 = 72 m².", "form": "anwenden", "zaehlt": "ja", "r": 12592}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Sportplatz hat eine Fläche von 7 200 m². Auf jedes Ar werden 2 kg Dünger gestreut. Wie viele kg Dünger werden gebraucht?"}, "o": {"wert": 144, "einheit": "kg"}, "h": "Wie viele m² hat ein Ar? Rechne zuerst die Fläche in Ar um.", "w": "1 a = 100 m². 7 200 m² = 72 a (7 200 : 100). 72 · 2 kg = 144 kg.", "form": "anwenden", "zaehlt": "ja", "r": 12593}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Fläche von 3 ha soll in m² angegeben werden. Weg A: Rechne mit 1 ha = 10 000 m². Weg B: Ein Quadrat mit 100 m Seitenlänge hat 1 ha. Bestimme die Fläche eines Quadrats mit 100 m Seitenlänge. Gib an, wie viele m² 3 ha sind."}, "o": {"wert": 30000, "einheit": "m²"}, "h": "Wie groß ist die Fläche eines Quadrats mit der Seitenlänge 100 m?", "w": "Weg A: 3 · 10 000 m² = 30 000 m². Weg B: Ein Quadrat hat 100 m · 100 m = 10 000 m². Drei Quadrate: 30 000 m².", "form": "zwei_wege", "zaehlt": "ja", "r": 12594}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Fläche wurde zuerst in dm² angegeben und dann in m² umgerechnet. Das Ergebnis lautet 8,4 m². Welche Zahl stand vorher in dm²?"}, "o": {"wert": 840, "einheit": "dm²"}, "h": "Wie viele dm² hat ein m²? Mache die Umrechnung rückgängig.", "w": "1 m² = 100 dm². Rückwärts wird mit 100 malgenommen: 8,4 m² = 8,4 · 100 dm² = 840 dm². Probe: 840 dm² = 8,4 m², denn 100 dm² = 1 m².", "form": "umkehren", "zaehlt": "ja", "r": 12595}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Mia berechnet 3,2 m² + 45 dm² und gibt das Ergebnis in m² an. Zeile 1: 1 m² sind 100 dm², also sind 45 dm² gleich 0,45 m². Zeile 2: 3,2 m² + 0,45 m² = 3,47 m². Zeile 3: Das Ergebnis ist 3,47 m². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile für sich und rechne beim Addieren Komma unter Komma nach. Welche Zeile enthält zuerst einen Fehler?", "w": "45 dm² = 0,45 m². 3,20 m² + 0,45 m² = 3,65 m². Richtig: 3,65 m². Der erste Fehler steht in Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 12596}, {"l": "zerlegen", "t": "zerlegen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein rechteckiger Garten ist 12 m lang und 9 m breit. In einer Ecke liegt ein rechteckiger Teich, der 5 m lang und 4 m breit ist. Wie groß ist die Fläche des Gartens ohne den Teich?"}, "o": {"wert": 88, "einheit": "m²"}, "h": "Berechne die Fläche des ganzen Rechtecks und die des Teichs. Was bleibt?", "w": "Ganzer Garten: 12 · 9 = 108 m². Teich: 5 · 4 = 20 m². Rest: 108 − 20 = 88 m².", "form": "anwenden", "zaehlt": "ja", "r": 12597}, {"l": "zerlegen", "t": "zerlegen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Aus einem Rechteck, das 10 m lang und 8 m breit ist, wird an einer Ecke ein kleineres Rechteck herausgeschnitten. Dieses ist 4 m lang. Die übrige Fläche beträgt 68 m². Wie breit ist das herausgeschnittene Rechteck?"}, "o": {"wert": 3, "einheit": "m"}, "h": "Welche Fläche hat das ganze Rechteck? Was sagt die übrige Fläche über das herausgeschnittene Stück?", "w": "Ganzes Rechteck: 10 · 8 = 80 m². Herausgeschnitten: 80 − 68 = 12 m². Breite: 12 : 4 = 3 m. Probe: 4 · 3 = 12 und 80 − 12 = 68.", "form": "umkehren", "zaehlt": "ja", "r": 12598}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt drei Bodenbeläge mit ihrem Preis je m². Ein Zimmer ist 6 m lang und 4 m breit. Wie viel Euro kostet der günstigste Belag für das ganze Zimmer?", "grafik": {"typ": "tabelle", "kopf": ["Belag", "Preis je m²"], "zeilen": [["Laminat", "18 €"], ["Teppich", "12 €"], ["Parkett", "35 €"]]}}, "o": {"wert": 288, "einheit": "€"}, "h": "Berechne zuerst die Fläche des Zimmers. Welcher Belag ist je m² am billigsten?", "w": "Fläche: 6 · 4 = 24 m². Der günstigste Belag ist Teppich mit 12 € je m². 24 · 12 = 288 €.", "form": "bruecke", "zaehlt": "ja", "r": 12599}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Gartenweg ist 6 m lang und 80 cm breit. Er wird lückenlos mit quadratischen Platten von 20 cm Seitenlänge belegt. Weg A: Teile die Fläche des Wegs durch die Fläche einer Platte (beides in cm²). Weg B: Bestimme, wie viele Platten in der Länge und wie viele in der Breite nebeneinander passen. Gib die Zahl der Platten an."}, "o": {"wert": 120, "einheit": "Platten"}, "h": "Rechne alle Maße in cm. Wie viele Platten von 20 cm passen in 6 m?", "w": "Weg A: Weg 600 cm · 80 cm = 48 000 cm², Platte 20 · 20 = 400 cm². 48 000 : 400 = 120. Weg B: 600 : 20 = 30 Platten in der Länge, 80 : 20 = 4 in der Breite. 30 · 4 = 120.", "form": "zwei_wege", "zaehlt": "ja", "r": 12600}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Quadrat und ein Rechteck haben denselben Flächeninhalt von 36 cm². Das Rechteck ist 9 cm lang. Um wie viel cm ist der Umfang des Rechtecks größer als der Umfang des Quadrats?"}, "o": {"wert": 2, "einheit": "cm"}, "h": "Fläche = Länge mal Breite. Mache das Malnehmen rückgängig und bestimme beide Umfänge.", "w": "Quadrat: 6 cm · 6 cm = 36 cm², also Seite 6 cm und Umfang 4 · 6 = 24 cm. Rechteck: Breite 36 : 9 = 4 cm, Umfang 2 · (9 + 4) = 26 cm. Unterschied: 26 − 24 = 2 cm. Probe: 9 · 4 = 36.", "form": "umkehren", "zaehlt": "ja", "r": 12601}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Bei einem Rechteck mit 5 cm Länge und 7 cm Breite werden Länge und Breite verdoppelt. Wie oft so groß wird dabei der Flächeninhalt und wie oft so groß der Umfang? Weg A: Berechne alte und neue Fläche und alten und neuen Umfang und teile jeweils. Weg B: Überlege, mit welcher Zahl jede Seite malgenommen wird und was das für Fläche und Umfang bedeutet. Gib die Summe der beiden Faktoren an."}, "o": {"wert": 6}, "h": "Vergleiche jeweils die neue mit der alten Größe: Wie oft passt die alte in die neue?", "w": "Weg A: Fläche 5 · 7 = 35 cm² wird 10 · 14 = 140 cm², das ist 4-mal so viel. Umfang 2 · (5 + 7) = 24 cm wird 2 · (10 + 14) = 48 cm, das ist 2-mal so viel. 4 + 2 = 6. Weg B: Jede Seite wird 2-mal so lang. Der Umfang besteht aus Seiten, er wird 2-mal so groß. Die Fläche ist Länge mal Breite, sie wird 2 · 2 = 4-mal so groß. 4 + 2 = 6.", "form": "zwei_wege", "zaehlt": "ja", "r": 12602}]$auf$::jsonb),
    (53, 'stochastik.kombinatorik', 533, 14, $auf$[{"l": "systematisch", "t": "systematisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Schreibe alle Wörter geordnet nach dem Anfangsbuchstaben auf und zähle. Weg B: Rechne: 3 Möglichkeiten für den ersten Platz, dann 2 für den zweiten, dann 1 für den dritten. Wie viele verschiedene dreibuchstabige Wörter kann man aus den Buchstaben A, B und C bilden, wenn jeder Buchstabe genau einmal vorkommt?"}, "o": {"wert": 6, "einheit": "Wörter"}, "h": "Schreibe zuerst alle Wörter mit A am Anfang auf. Wie viele sind es?", "w": "Weg A: ABC, ACB, BAC, BCA, CAB, CBA sind 6 Wörter. Weg B: 3 · 2 · 1 = 6.", "form": "zwei_wege", "zaehlt": "ja", "r": 12534}, {"l": "systematisch", "t": "systematisch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Kind hat 5 Hosen und 4 T-Shirts. Mit mehreren Jacken kann es genau 60 verschiedene Outfits aus je einer Hose, einem T-Shirt und einer Jacke zusammenstellen. Wie viele Jacken hat es?"}, "o": {"wert": 3, "einheit": "Jacken"}, "h": "Wie viele Outfits gibt es nur mit Hose und T-Shirt? Wie oft passt das in 60?", "w": "Hose und T-Shirt ergeben 5 · 4 = 20 Möglichkeiten. Mit der Jacke: 20 · Jacken = 60, also Jacken = 60 : 20 = 3.", "form": "umkehren", "zaehlt": "ja", "r": 12535}, {"l": "zaehlprinzip", "t": "zaehlprinzip", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Eisdiele bietet 6 Eissorten an. Man kann einen Becher mit genau einer Sorte und genau einer Soße bestellen. So gibt es 42 verschiedene Becher. Wie viele Soßen gibt es?"}, "o": {"wert": 7, "einheit": "Soßen"}, "h": "Jede Sorte lässt sich mit jeder Soße zu einem Becher kombinieren. Mache das Malnehmen rückgängig.", "w": "Sorten · Soßen = 42, also Soßen = 42 : 6 = 7. Probe: 6 · 7 = 42.", "form": "umkehren", "zaehlt": "ja", "r": 12536}, {"l": "zaehlprinzip", "t": "zaehlprinzip", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Baumdiagramm hat in der ersten Stufe 3 Äste. An jedem dieser Äste gibt es in der zweiten Stufe 2 Äste und an jedem davon in der dritten Stufe 4 Äste. Wie viele Pfade führen von der Wurzel bis zu den Enden?"}, "o": {"wert": 24, "einheit": "Pfade"}, "h": "Jeder Pfad geht durch alle drei Stufen. Wie viele Möglichkeiten gibt es in jeder Stufe?", "w": "Die Zahl der Pfade ist das Produkt der Astzahlen: 3 · 2 · 4 = 24.", "form": "bruecke", "zaehlt": "ja", "r": 12537}, {"l": "reihenfolgen", "t": "reihenfolgen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Weg A: Wähle nacheinander das Kind für den 1., 2., 3. und 4. Platz und multipliziere die Möglichkeiten. Weg B: Schreibe zuerst alle Reihenfolgen für 3 Kinder auf (es sind 6) und überlege, an wie vielen Stellen das vierte Kind eingefügt werden kann. Auf wie viele Arten können 4 Kinder in einer Reihe stehen?"}, "o": {"wert": 24, "einheit": "Möglichkeiten"}, "h": "Wenn 3 Kinder in einer Reihe stehen: An wie vielen Stellen kann sich ein viertes Kind einreihen (auch ganz vorn und ganz hinten)?", "w": "Weg A: 4 · 3 · 2 · 1 = 24. Weg B: Bei jeder der 6 Reihenfolgen von 3 Kindern kann das vierte Kind an 4 Stellen stehen (vorn, zwei Lücken, hinten): 6 · 4 = 24.", "form": "zwei_wege", "zaehlt": "ja", "r": 12538}, {"l": "reihenfolgen", "t": "reihenfolgen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Fotografin stellt 6 Kinder in einer Reihe auf. Tim und Eva sollen unmittelbar nebeneinander stehen, und zwar Tim links neben Eva. Wie viele verschiedene Aufstellungen gibt es?"}, "o": {"wert": 120, "einheit": "Aufstellungen"}, "h": "Tim und Eva müssen immer nebeneinander stehen. Wie ändert das, was du anordnest?", "w": "Tim und Eva bilden ein festes Paar (Tim links). Es werden 5 Teile angeordnet: das Paar und 4 weitere Kinder. 5 · 4 · 3 · 2 · 1 = 120 Aufstellungen.", "form": "anwenden", "zaehlt": "ja", "r": 12539}, {"l": "baumdiagramm", "t": "baumdiagramm", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Glücksrad hat 4 gleich große Felder A, B, C und D. Es wird einmal gedreht, danach wird eine Münze geworfen (Kopf oder Zahl). Wie viele Pfade hat das Baumdiagramm für diesen Versuch?"}, "o": {"wert": 8, "einheit": "Pfade"}, "h": "In der ersten Stufe gibt es mehrere Äste, an jedem hängen weitere Äste der zweiten Stufe.", "w": "Erste Stufe: 4 Äste (A, B, C, D). An jedem Ast hängen 2 Äste (Kopf, Zahl). 4 · 2 = 8 Pfade.", "form": "anwenden", "zaehlt": "ja", "r": 12540}, {"l": "baumdiagramm", "t": "baumdiagramm", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Münze wird 4-mal geworfen. Weg A: Zeichne den Baum und zähle die passenden Pfade. Weg B: Überlege, an welcher der 4 Stellen der einzige Kopf stehen kann. Bei wie vielen der Ergebnisfolgen kommt genau 1-mal Kopf vor?"}, "o": {"wert": 4, "einheit": "Folgen"}, "h": "Alle anderen Würfe sind Zahl. Es kommt nur darauf an, wann der Kopf fällt.", "w": "Weg A: KZZZ, ZKZZ, ZZKZ, ZZZK sind die passenden Pfade, das sind 4. Weg B: Der Kopf kann beim 1., 2., 3. oder 4. Wurf fallen: 4 Möglichkeiten.", "form": "zwei_wege", "zaehlt": "ja", "r": 12541}, {"l": "bedingungen", "t": "bedingungen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zahlenschloss hat zwei Rädchen. Am ersten Rädchen steht eine ungerade Ziffer (1, 3, 5, 7 oder 9), am zweiten eine gerade Ziffer (0, 2, 4, 6 oder 8). Wie viele verschiedene Codes sind möglich?"}, "o": {"wert": 25, "einheit": "Codes"}, "h": "Wie viele Möglichkeiten gibt es am ersten, wie viele am zweiten Rädchen?", "w": "Erstes Rädchen: 5 Möglichkeiten. Zweites Rädchen: 5 Möglichkeiten. Zusammen 5 · 5 = 25 Codes.", "form": "anwenden", "zaehlt": "ja", "r": 12542}, {"l": "bedingungen", "t": "bedingungen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Aus n verschiedenen Ziffern ohne die Null werden dreistellige Zahlen ohne doppelte Ziffer gebildet. Es gibt genau 60 solche Zahlen. Wie groß ist n?"}, "o": {"wert": 5}, "h": "Wie viele Möglichkeiten gibt es für die erste, die zweite und die dritte Stelle? Probiere kleine Werte für n.", "w": "Für die erste Stelle gibt es n Möglichkeiten, für die zweite n − 1, für die dritte n − 2. Für n = 5 ist 5 · 4 · 3 = 60. Für n = 4 wäre es 24, für n = 6 wären es 120. Also ist n = 5.", "form": "umkehren", "zaehlt": "ja", "r": 12543}, {"l": "grenzen", "t": "grenzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "6 Personen begrüßen sich bei einem Treffen, indem jede jeder anderen genau einmal die Hand gibt. Weg A: Zähle der Reihe nach: Die erste Person gibt 5 Handschläge, die zweite noch 4 neue und so weiter. Weg B: Jede der 6 Personen gibt 5 Handschläge; dabei wird jeder Handschlag zweimal gezählt. Wie viele Handschläge gibt es?"}, "o": {"wert": 15, "einheit": "Handschläge"}, "h": "Bei Weg B: Wie oft wird ein einzelner Handschlag gezählt? Was musst du am Ende tun?", "w": "Weg A: 5 + 4 + 3 + 2 + 1 = 15. Weg B: 6 · 5 = 30, aber jeder Handschlag wurde zweimal gezählt: 30 : 2 = 15.", "form": "zwei_wege", "zaehlt": "ja", "r": 12544}, {"l": "grenzen", "t": "grenzen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Sechseck hat 6 Ecken. Eine Diagonale ist eine Strecke zwischen zwei Ecken, die nicht nebeneinander liegen. Wie viele Diagonalen hat das Sechseck?"}, "o": {"wert": 9, "einheit": "Diagonalen"}, "h": "Wie viele Strecken gibt es zwischen allen Paaren von Ecken? Wie viele davon sind Seiten des Sechsecks?", "w": "Zwischen 6 Ecken gibt es 6 · 5 : 2 = 15 Strecken. 6 davon sind Seiten des Sechsecks. Die übrigen 15 − 6 = 9 sind Diagonalen.", "form": "bruecke", "zaehlt": "ja", "r": 12545}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Eis-Imbiss wirbt: „Über 100 verschiedene Eisbecher!“ Man wählt genau eine von 6 Sorten, genau eine von 4 Soßen und genau eines von 3 Toppings. Stimmt die Werbung?"}, "a": ["Nein, es sind nur 13 Becher.", "Ja, es sind 7 · 5 · 4 = 140 Becher.", "Nein, es sind nur 72 Becher."], "o": {"index": 2}, "h": "Aus jeder Gruppe wird genau eines gewählt. Wie viele Kombinationen gibt es nach dem Zählprinzip?", "w": "Nach dem Zählprinzip: 6 · 4 · 3 = 72 Becher. 72 ist weniger als 100, die Werbung stimmt nicht.", "form": "anwenden", "zaehlt": "ja", "r": 12546}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Tim behauptet: „Aus den Ziffern 1 und 2 kann man nur 6 verschiedene dreistellige Zahlen bilden, denn es gibt 3 · 2 · 1 Anordnungen.“ Aus den Ziffern 1 und 2 sollen dreistellige Zahlen gebildet werden, wobei Ziffern mehrfach vorkommen dürfen. Weg A: Schreibe alle Zahlen geordnet auf (111, 112, 121, …) und zähle. Weg B: Rechne mit der Zahl der Möglichkeiten für jede Stelle. Gib die richtige Zahl der dreistelligen Zahlen an."}, "o": {"wert": 8, "einheit": "Zahlen"}, "h": "Darf eine Ziffer mehrfach vorkommen? Wie viele Ziffern kommen dann für jede Stelle in Frage?", "w": "Weg A: 111, 112, 121, 122, 211, 212, 221, 222 sind 8 Zahlen. Weg B: Jede der 3 Stellen hat 2 Möglichkeiten: 2 · 2 · 2 = 8. 3 · 2 · 1 zählt Anordnungen von drei verschiedenen Ziffern, die jeweils einmal vorkommen. Hier stehen nur 1 und 2 zur Wahl, mit Wiederholung.", "form": "zwei_wege", "zaehlt": "ja", "r": 12547}]$auf$::jsonb),
    (67, 'groessen.proportional', 633, 10, $auf$[{"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "5 Äpfel kosten 2 €. Weg A: Berechne zuerst den Preis für 1 Apfel und rechne dann mit 12. Weg B: Überlege, das Wievielfache von 5 die Zahl 12 ist, und nimm den Preis für 5 Äpfel mit diesem Faktor mal. Was kosten 12 Äpfel?"}, "o": {"wert": 4.8, "einheit": "€"}, "h": "Bei Weg B: Wie oft passt 5 in 12? Das Ergebnis ist keine ganze Zahl.", "w": "Weg A: 1 Apfel kostet 2 € : 5 = 0,40 €. 12 Äpfel: 12 · 0,40 € = 4,80 €. Weg B: 12 : 5 = 2,4. 2,4 · 2 € = 4,80 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 12634}, {"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Pumpe fördert in 8 Minuten 120 Liter Wasser. Wie viele Liter fördert sie in einer Stunde?"}, "o": {"wert": 900, "einheit": "Liter"}, "h": "Auf welche gemeinsame Zeiteinheit musst du die Angaben bringen? Was lässt sich zuerst ausrechnen?", "w": "In 1 Minute: 120 : 8 = 15 Liter. Eine Stunde hat 60 Minuten: 15 · 60 = 900 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 12635}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Lastwagen fährt in 3 Stunden 240 km. Er fährt immer gleich schnell. Wie weit kommt er in 5 Stunden?"}, "o": {"wert": 400, "einheit": "km"}, "h": "Wie weit fährt er in einer Stunde?", "w": "In 1 Stunde: 240 km : 3 = 80 km. In 5 Stunden: 5 · 80 km = 400 km.", "form": "anwenden", "zaehlt": "ja", "r": 12636}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Kopierer druckt 90 Blätter in 6 Minuten. Weg A: Bestimme, wie viele Blätter er pro Minute druckt, und teile 330 durch diese Zahl. Weg B: Überlege, wie lange 270 Blätter dauern, und rechne die restlichen 60 Blätter dazu. Wie lange braucht er für 330 Blätter?"}, "o": {"wert": 22, "einheit": "min"}, "h": "Bei Weg B: 270 Blätter sind das Dreifache von 90 Blättern. Wie lange dauern 60 Blätter?", "w": "Weg A: 90 : 6 = 15 Blätter je Minute. 330 : 15 = 22 Minuten. Weg B: 270 Blätter brauchen 3 · 6 = 18 Minuten. 60 Blätter brauchen 60 : 15 = 4 Minuten. 18 + 4 = 22 Minuten.", "form": "zwei_wege", "zaehlt": "ja", "r": 12637}, {"l": "geschickt", "t": "dreisatz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "36 Eier kosten 9 €. Wie viele Eier bekommt man für 2,50 €?"}, "o": {"wert": 10, "einheit": "Eier"}, "h": "Wie viele Eier bekommst du für 1 €? Und für 0,50 €?", "w": "36 Eier kosten 9 €, also bekommt man 4 Eier für 1 € und 2 Eier für 0,50 €. 2,50 € sind 2 € + 0,50 €: 2 · 4 + 2 = 10 Eier. Probe: 10 Eier kosten 10 · 0,25 € = 2,50 €.", "form": "umkehren", "zaehlt": "ja", "r": 12638}, {"l": "geschickt", "t": "dreisatz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle gehört zu einer proportionalen Zuordnung (Anzahl Hefte → Preis). Wie viel Euro kosten 14 Hefte?", "grafik": {"typ": "tabelle", "kopf": ["Hefte", "Preis in €"], "zeilen": [["4", "6"], ["6", "9"], ["10", "15"]]}}, "o": {"wert": 21, "einheit": "€"}, "h": "Aus welchen Heftzahlen der Tabelle kannst du 14 zusammensetzen? Was bedeutet das für die Preise?", "w": "14 Hefte sind 4 Hefte und 10 Hefte. Preis: 6 € + 15 € = 21 €. Kontrolle: Ein Heft kostet 1,50 €, 14 · 1,50 € = 21 €.", "form": "bruecke", "zaehlt": "ja", "r": 12639}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt ein Rezept für 4 Personen. Wie viel Gramm Butter braucht man für 10 Personen?", "grafik": {"typ": "tabelle", "kopf": ["Zutat", "Menge für 4 Personen"], "zeilen": [["Mehl", "200 g"], ["Zucker", "80 g"], ["Butter", "120 g"]]}}, "o": {"wert": 300, "einheit": "g"}, "h": "Wie viel Butter braucht eine Person?", "w": "Für 1 Person: 120 g : 4 = 30 g Butter. Für 10 Personen: 10 · 30 g = 300 g.", "form": "bruecke", "zaehlt": "ja", "r": 12640}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Mit einer Tankfüllung von 45 Litern kommt ein Auto 900 km weit. Wie viele Liter verbraucht es auf 100 km?"}, "o": {"wert": 5, "einheit": "Liter"}, "h": "Wie viele Hunderter sind 900 km? Verteile die 45 Liter darauf.", "w": "900 km sind 9 mal 100 km. 45 Liter : 9 = 5 Liter. Das Auto verbraucht 5 Liter auf 100 km.", "form": "umkehren", "zaehlt": "ja", "r": 12641}, {"l": "aenderung", "t": "aenderung", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt die Temperatur an einem Morgen. Sie steigt gleichmäßig. Um wie viel Grad steigt sie pro Stunde?", "grafik": {"typ": "tabelle", "kopf": ["Uhrzeit", "Temperatur in °C"], "zeilen": [["8 Uhr", "12"], ["10 Uhr", "18"], ["12 Uhr", "24"]]}}, "o": {"wert": 3, "einheit": "°C"}, "h": "Wie viele Grad kommen zwischen 8 Uhr und 12 Uhr dazu? Wie viele Stunden sind das?", "w": "Von 8 Uhr bis 12 Uhr steigt die Temperatur um 24 − 12 = 12 Grad in 4 Stunden. Pro Stunde: 12 : 4 = 3 Grad.", "form": "bruecke", "zaehlt": "ja", "r": 12642}, {"l": "aenderung", "t": "aenderung", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Becken wird gleichmäßig gefüllt. Nach 2 Stunden sind 800 Liter im Becken, nach 5 Stunden 2 000 Liter. Wie viele Liter sind nach 8 Stunden im Becken?"}, "o": {"wert": 3200, "einheit": "Liter"}, "h": "Wie viele Liter kommen pro Stunde dazu? Wie viele Stunden sind es noch bis zur 8. Stunde?", "w": "Von der 2. bis zur 5. Stunde kommen 1 200 Liter in 3 Stunden dazu, also 400 Liter je Stunde. Von der 5. bis zur 8. Stunde noch einmal 3 · 400 = 1 200 Liter. 2 000 + 1 200 = 3 200 Liter.", "form": "anwenden", "zaehlt": "ja", "r": 12643}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 210 then fehler := fehler || ('zusammen ' || gesamt || ' statt 210')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (1, 4, 13, 28, 39, 41, 44, 47, 49, 50, 51, 53, 67) group by 1 order by 1;
